_SOURCES['kagg.economics.production'] = '"""What a single tile actually produces over a season.\n\nThe published Object Types table lists a "max yield / tile / day" column that does not\nmean what it looks like for ongoing crops.\n`_daily_refresh_plants` stops an ongoing crop once `production_count > max_yield`, so the cap\nis on production *events*, not on units and certainly not per day. Unfertilized, a tomato or\nstrawberry tile yields four units for its whole life and then dies. Fertilized, each event\ngrants 2 instead of 1, so the same four events yield **eight**.\nAnimals are the opposite: there is no lifetime cap, so they produce until they starve.\n\nGetting this wrong by an order of magnitude changes every strategic conclusion, so the\nconstants here are measured in the live environment by :func:`probe_crop` and\n:func:`probe_animal`, and `tests/test_production.py` re-measures them on every run.\n\nAll figures are single-tile, one farmer, no animal CARE bonus, 30-day season.\nCARE is unexercised, so the animal numbers are floors too.\n"""\n\nfrom typing import NamedTuple\n\nfrom kaggle_environments.envs.kaggriculture import kaggriculture as kg\n\nSEASON_DAYS = 30\n\n# Units one tile yields over a season under optimal play, WITHOUT fertilizer.\n# These are floors, not ceilings -- see TILE_YIELD_FERTILIZED.\nTILE_YIELD_PER_SEASON = {\n    "WHEAT": 28,\n    "CARROT": 29,\n    "TOMATO": 8,\n    "STRAWBERRY": 6,\n    "MELON": 12,\n}\n\n# With fertilizer kept active, measured the same way.\n#\n# Fertilizer **doubles** ongoing-crop lifetime output, which is not obvious and matters a lot.\n# The lifetime cap is on production *events* (`production_count > max_yield`), while\n# `yield_units` is only a *holding* cap. A fertilized event adds 2 units instead of 1, so\n# harvesting between events collects 2 x max_yield over the plant\'s life instead of max_yield.\n#\n# Melon gains nothing: its watering window already fills `max_yield` unfertilized.\nTILE_YIELD_FERTILIZED = {\n    "WHEAT": 42,\n    "CARROT": 39,\n    "TOMATO": 16,\n    "STRAWBERRY": 12,\n    "MELON": 12,\n}\n\n# Fertilizer is free from animals: every fed animal sets `fertilizer_available` daily and\n# COLLECT_FERTILIZER takes it for one action. Buying it instead costs $100 base.\n# This is the wheat -> animal -> fertilizer -> premium-crop loop, and it is the main\n# structural reason to keep animals.\nFERTILIZER_MARKET_BASE = 100\nFERTILIZER_ACTIVE_DAYS = 3  # FERTILIZE sets fertilized_until_day = day + 2, inclusive\n\n# Units one animal yields over a season, fed every day, harvested before it fills.\n# Keyed by product rather than animal, since that is what the market trades.\nANIMAL_YIELD_PER_SEASON = {\n    "EGG": 26,\n    "MILK": 11,\n    "WOOL": 8,\n}\n\n# Seeds actually bought and planted per tile per season, measured. A final cycle that cannot\n# finish before day 29 is still planted and still paid for, which `SEASON_DAYS // cycle_days`\n# missed for strawberry (2 not 1) and tomato (3 not 2).\nPLANTINGS_PER_SEASON = {"WHEAT": 8, "CARROT": 11, "TOMATO": 3, "STRAWBERRY": 2, "MELON": 3}\nPLANTINGS_FERTILIZED = dict(PLANTINGS_PER_SEASON)  # measured identical: fertilizer changes\n# units per event, not the number of cycles that fit in a season.\n\nPRODUCT_TO_ANIMAL = {a["product"]: name for name, a in kg.ANIMALS.items()}\n\n\ndef cycle_days(crop):\n    """Days from planting to the harvest that clears the tile."""\n    cd = kg.CROPS[crop]\n    if cd["ongoing"]:\n        # Productions land every `interval` days from `first_yield_day`, `max_yield` times.\n        return cd["first_yield_day"] + cd["interval"] * (cd["max_yield"] - 1)\n    return cd["max_yield_day"]\n\n\ndef first_harvest_day(crop):\n    """Earliest day a full-value harvest is available from a day-0 planting."""\n    return cycle_days(crop)\n\n\ndef units_per_cycle(crop):\n    """Units a single planting yields, played optimally and without fertilizer."""\n    cd = kg.CROPS[crop]\n    if cd["ongoing"]:\n        return cd["max_yield"]\n    # Starts at 1 unit; each watering inside the window adds 1, capped at max_yield.\n    window_start = (cd["max_yield_day"] + 1) // 2\n    waterings = cd["max_yield_day"] - window_start + 1\n    return min(cd["max_yield"], 1 + waterings)\n\n\ndef seed_cost_per_tile_season(crop, fertilized=False):\n    """Total seed spend to keep one tile planted all season.\n\n    Uses the *measured* number of plantings rather than `SEASON_DAYS // cycle_days`, which\n    disagreed with what the probe actually spends: a cycle that cannot finish before the season\n    ends is still planted and still paid for, so strawberry costs two seeds and tomato three,\n    not the one and two the division predicted.\n    """\n    table = PLANTINGS_FERTILIZED if fertilized else PLANTINGS_PER_SEASON\n    return kg.CROPS[crop]["seed"] * table[crop]\n\n\nclass ProbeResult(NamedTuple):\n    """What a single-tile probe measured: total units, and when things happened."""\n\n    units: int\n    harvests: list  # [(day, units), ...]\n    plantings: list  # [day, ...] -- one seed bought and spent per entry\n\n\ndef probe_crop(crop, seed=3, days=SEASON_DAYS, fertilize=False):\n    """Play one farmer on one tile optimally for `crop`; return a :class:`ProbeResult`.\n\n    With `fertilize=True` the tile is kept under fertilizer continuously, bought from the\n    market. That doubles ongoing-crop lifetime output (see `TILE_YIELD_FERTILIZED`) and for\n    non-ongoing crops fills the watering window faster.\n\n    Non-ongoing crops are held until the watering window closes, because harvesting clears\n    the tile and an early harvest throws away the remaining bonus waterings.\n    Ongoing crops accumulate on the tile and are taken in one go, which is both\n    action-efficient and what makes late selling possible.\n    """\n    from kaggle_environments import make\n\n    cd = kg.CROPS[crop]\n    harvests = []\n    plantings = []\n\n    def agent(obs, cfg):\n        day = obs["day"]\n        farm = obs["farms"][0]\n        fx, fy = farm["farmer"]\n        tile = farm["tiles"][fy][fx]\n        private = obs["private"]\n        seeds = private["seeds"]\n        shed = private["shed"]\n        carried = private["inventories"][0] if private.get("inventories") else {}\n\n        market = [["BUY_SEED", crop, 1]] if seeds.get(crop, 0) < 1 else []\n        if fertilize and shed.get("FERTILIZER", 0) + carried.get("FERTILIZER", 0) < 2:\n            market.append(["BUY_PRODUCT", "FERTILIZER", 2])\n\n        act = ["PASS"]\n        if tile is None:\n            if seeds.get(crop, 0) >= 1:\n                act = ["PLANT", crop]\n                plantings.append(day)\n        elif isinstance(tile, dict) and tile.get("kind") == "WEED":\n            act = ["DIG"]\n        elif isinstance(tile, dict) and tile.get("kind") == "PLANT":\n            age = day - tile["planted_day"]\n            units = tile.get("yield_units", 0)\n            # Ongoing crops are harvested eagerly: `yield_units` is a holding cap, so leaving\n            # units on the tile throws away the next event\'s production. Non-ongoing crops are\n            # held until the watering window closes, because harvest clears the tile.\n            ripe = units > 0 if cd["ongoing"] else age >= cd["max_yield_day"]\n            # Near the end there is no time left to fill the tile, so take what is standing.\n            flush = day >= days - 1 and units > 0\n            needs_fert = fertilize and tile.get("fertilized_until_day", -1) < day\n\n            if not tile.get("watered_today"):\n                act = ["WATER"]\n            elif needs_fert:\n                act = ["FERTILIZE"] if carried.get("FERTILIZER", 0) >= 1 else ["PICKUP", "FERTILIZER", 2]\n            elif (ripe or flush) and units > 0 and age >= cd["first_yield_day"]:\n                act = ["HARVEST"]\n                harvests.append((day, units))\n        return {"farmer": act, "hands": [], "market": market}\n\n    env = make("kaggriculture", configuration={"seed": seed}, debug=False)\n    env.run([agent, "pass"])\n    return ProbeResult(sum(u for _, u in harvests), harvests, plantings)\n\n\ndef probe_animal(product, seed=3):\n    """Place one animal, feed it daily from bought wheat, harvest whenever it holds units.\n\n    Returns (total_units, harvests). Wheat for feed is bought from the market rather than\n    grown, which keeps the measurement about the animal instead of about a wheat operation.\n\n    The structure is built on the farmer\'s spawn tile, which is one of the four shed-access\n    tiles, so `PICKUP` and `FEED` both work without the farmer ever moving.\n    PLACE and FEED draw from the unit\'s carried inventory, not the shed, and that inventory\n    is emptied back into the shed every night -- hence the daily PICKUP.\n    """\n    from kaggle_environments import make\n\n    animal = PRODUCT_TO_ANIMAL[product]\n    structure = kg.ANIMALS[animal]["structure"]\n    harvests = []\n\n    def agent(obs, cfg):\n        day = obs["day"]\n        farm = obs["farms"][0]\n        fx, fy = farm["farmer"]\n        tile = farm["tiles"][fy][fx]\n        private = obs["private"]\n        shed = private["shed"]\n        carried = private["inventories"][0] if private.get("inventories") else {}\n        placed = isinstance(tile, dict) and "animal" in tile\n        market = []\n\n        if shed.get("WHEAT", 0) + carried.get("WHEAT", 0) < 4:\n            market.append(["BUY_PRODUCT", "WHEAT", 10])\n        if not placed and shed.get(animal, 0) + carried.get(animal, 0) < 1:\n            market.append(["BUY_ANIMAL", animal, 1])\n\n        act = ["PASS"]\n        if tile is None:\n            act = ["BUILD_COOP"] if structure == "COOP" else ["BUILD_PASTURE"]\n        elif isinstance(tile, dict) and tile.get("kind") == structure and not placed:\n            if carried.get(animal, 0) >= 1:\n                act = ["PLACE", animal]\n            elif shed.get(animal, 0) >= 1:\n                act = ["PICKUP", animal, 1]\n        elif placed:\n            if tile.get("yield_units", 0) > 0:\n                act = ["HARVEST"]\n                harvests.append((day, tile["yield_units"]))\n            elif not tile["fed_today"]:\n                act = ["FEED"] if carried.get("WHEAT", 0) >= 1 else ["PICKUP", "WHEAT", 2]\n        return {"farmer": act, "hands": [], "market": market}\n\n    env = make("kaggriculture", configuration={"seed": seed}, debug=False)\n    env.run([agent, "pass"])\n    return ProbeResult(sum(u for _, u in harvests), harvests, [])\n'
_SOURCES['kagg.search.routines'] = '"""Macro-routines: the chain is the unit of search, not the sub-action.\n\n**Why this module exists.** A sub-action search cannot find the animal economy, and that is a\nstructural fact rather than a tuning problem. Two mechanics close the door:\n\n- `consecutive_unfed >= 2` escapes the animal (`kaggriculture.py:786`), so buying one you will not\n  feed every day is a *deterministic* loss of $300-$500, not a bad expectation.\n- FEED is illegal until an animal is on the board, unfed, with a unit standing on it carrying wheat\n  (`jax_masks.py:93`), so a policy samples FEED from a distribution where it has zero mass.\n\nEvery prefix of the chain is therefore money-negative and every complete chain needs ~15 coordinated\nedits at specific tiles on specific days. A hill-climber selecting on money rejects step one forever;\nPPO learns to stop buying animals, which re-masks FEED and closes the loop. Both failures are the\nsame wall.\n\nThe fix is not a better optimiser. It is a representation in which a partial chain **cannot be\nexpressed**. A routine emits the whole chain or nothing, so the valley is not crossed -- it is not in\nthe space. What the search then owns is *which* routine, *where*, *when* and *how many*, which is\nstrategy, while correctness lives in the decoder.\n\n**The ranch cell.** The four shed-access tiles are `(4,4) (5,4) (4,5) (5,5)` -- the inner corners\naround the shed. PICKUP, DROP and shed-PLACE test only shed-adjacency, and FEED/CARE/HARVEST test\nonly that the unit stands on the animal\'s tile. Put the pen *on* a shed-access tile and one unit can\nrun the entire loop -- draw feed, feed, care, harvest, deposit -- **without ever moving**, in 5 of\nthe day\'s 24 turns. That matters beyond convenience: a unit\'s tile is the cumulative sum of its\nmovement ops, so in an open-loop script one edited step silently invalidates every later op. A\nzero-movement routine has no such coupling, which is what makes it a safe unit of search.\n\n**Land is the gate.** Only `(4,4)` is in NW, the sole quadrant unlocked at the start; the other three\ncells begin LOCKED. `LAND_ORDER` is `[\'NE\',\'SW\',\'SE\']` at `[1000, 2000, 4000]`, bought in sequence,\nso cell `(5,5)` costs $7,000 of land to reach. This is also why an agent that never buys land plays\nthe whole season on 25 tiles of 100.\n"""\n\nimport numpy as np\n\n# ---------------------------------------------------------------------------\n# The reference\'s own tables, mirrored. Kept as literals rather than imported so this module has no\n# dependency on `reference/`, and pinned by `tests/test_routines.py` against the geometry helpers.\n# ---------------------------------------------------------------------------\n\nOP_NAMES = [\n    "PASS", "NORTH", "SOUTH", "EAST", "WEST",\n    "WATER", "HARVEST", "PLANT", "DIG",\n    "PICKUP", "DROP", "PLACE", "FEED", "CARE", "COLLECT_FERTILIZER", "FERTILIZE",\n    "BUILD_COOP", "BUILD_PASTURE",\n]\nOP = {n: i for i, n in enumerate(OP_NAMES)}\n\nPRODUCTS = ["WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON", "EGG", "MILK", "WOOL", "FERTILIZER"]\nCROPS = ["WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON"]\nANIMAL_NAMES = ["GOOSE", "COW", "SHEEP"]\nITEMS = PRODUCTS + ANIMAL_NAMES          # the `unit_item` domain, 12 wide\n\nANIMALS = {\n    "GOOSE": {"cost": 300, "structure": "COOP",    "first_yield_day": 4, "interval": 1, "max_held": 4, "product": "EGG"},\n    "COW":   {"cost": 400, "structure": "PASTURE", "first_yield_day": 8, "interval": 2, "max_held": 6, "product": "MILK"},\n    "SHEEP": {"cost": 500, "structure": "PASTURE", "first_yield_day": 6, "interval": 3, "max_held": 6, "product": "WOOL"},\n}\nSTRUCTURE_OP = {"COOP": OP["BUILD_COOP"], "PASTURE": OP["BUILD_PASTURE"]}\n\nLAND_ORDER = ["NE", "SW", "SE"]\nLAND_PRICES = [1000, 2000, 4000]\n\nBOARD_SIZE = 10\nTURNS_PER_DAY = 24\nSEASON_DAYS = 30\nT_DEFAULT = 719          # the recorder\'s length: 30 days of 24 turns, minus the unplayed last turn\nU_DEFAULT = 24\n\n\ndef quadrant_of(x, y, board_size=BOARD_SIZE):\n    half = board_size // 2\n    return ("N" if y < half else "S") + ("W" if x < half else "E")\n\n\ndef shed_access_tiles(board_size=BOARD_SIZE):\n    """The four inner-corner tiles around the shed, in the reference\'s NWSE order."""\n    half = board_size // 2\n    return [(half - 1, half - 1), (half, half - 1), (half - 1, half), (half, half)]\n\n\nSPAWN = (4, 4)          # `_default_spawn`: the only shed-access tile inside the starting quadrant\n\n\ndef spawn_order(board_size=BOARD_SIZE, n=8):\n    """Unit index -> the tile that unit spawns on at dawn.\n\n    Mirrors `_spawn_hand`: minimum occupancy over the shed-access tiles, ties broken by NWSE index.\n    The farmer occupies `(4,4)` first, so hands land on `(5,4)`, `(4,5)`, `(5,5)` in that order --\n    **exactly one per ranch cell, with no movement required by any of them.**\n\n    Note it does *not* filter for unlocked quadrants, so a hand really does spawn on a LOCKED tile.\n    It can still PICKUP and DROP there (those test only shed-adjacency) but cannot BUILD, because a\n    LOCKED tile is the string `"LOCKED"` rather than `None`.\n    """\n    tiles = shed_access_tiles(board_size)\n    occ = {t: 0 for t in tiles}\n    occ[tuple(SPAWN)] += 1\n    order = [tuple(SPAWN)]\n    for _ in range(n):\n        best = min(occ.items(), key=lambda kv: (kv[1], tiles.index(kv[0])))[0]\n        order.append(best)\n        occ[best] += 1\n    return order\n\n\ndef spawn_tile(unit, board_size=BOARD_SIZE):\n    """Where `unit` actually stands at dawn -- which is `SPAWN` only for unit 0 and its cycle.\n\n    Hands fill the shed-access tiles in NWSE order and wrap every four, so unit 2 wakes on `(4,5)`\n    and unit 3 on `(5,5)`. `grow()` routed every unit from `SPAWN` regardless, which is a correct\n    walk from the wrong origin: the unit arrives displaced by the difference, and then PLANT, WATER\n    and HARVEST land on tiles it does not own and silently no-op. Measured on one melon block, same\n    chain, only the unit changed: $15,575 for unit 0 against $5,402 for unit 2 and $1,920 for unit 3.\n    """\n    return spawn_order(board_size, n=unit + 1)[unit]\n\n\ndef dawn_crew(hands, board_size=BOARD_SIZE, per_turn=2):\n    """Hire `hands` hands two per turn, and say where each one wakes and when it can first act.\n\n    `spawn_tile` above is a table indexed by unit, and that is only correct for a crew hired in a\n    single turn -- which is not how the spawn rule works. `_spawn_hand` (`kaggriculture.py:508`) picks\n    the **minimum-occupancy** shed-access tile in NWSE order **at the moment the HIRE settles**, so the\n    tile a hand gets depends on where everyone is standing then. Hiring four at once with the farmer on\n    `(4,4)` gives `(5,4)`, `(4,5)`, `(5,5)`, `(4,4)` -- and `(5,5)` is SE, whose only neighbours are\n    `(5,4)` in NE and `(4,5)` in SW. Both are LOCKED until land is bought, `_apply_unit_action` ignores\n    a move onto LOCKED without spending the turn, and the hand emits a whole day of ops onto a tile it\n    does not own. Silently: nothing raises, and our own op census still counts them as done.\n\n    Measured on the tape\'s schedule, before this existed: every unit spent 139-505 turns on a tile the\n    emitter did not believe in, and 76 of 126 PLANT ops were refused -- 27 LOCKED and 43 OCCUPIED,\n    because a displaced hand works its neighbour\'s tile.\n\n    **Two per turn is the cadence that makes the tile predictable.** With the farmer parked on `(4,4)`\n    and every earlier hand walked home to it, occupancy is `{(4,4): 1+k}` and the two picks are always\n    `(5,4)` and `(4,5)` -- one step from the shed, never `(5,5)`. Each pair then steps onto `(4,4)` on\n    its first turn, which restores the invariant before the next pair settles. Three per turn would put\n    the third hand back on `(5,5)`, and a hand there needs two turns to reach `(4,4)`, which breaks the\n    occupancy assumption for every batch after it.\n\n    The tape does the same thing: `[(1, 2), (2, 2), (3, 2)]` on day 1, with its farmer doing shed and\n    pen work on `(4,4)` through hour 7.\n\n    Returns `(batches, spawn, ready)` -- `[(turn_in_day, count)]`, `{unit: tile}`, `{unit: first turn\n    of the day the unit may act}`. Unit 0 is the farmer: it exists from turn 1 but must hold `(4,4)`\n    until the last batch has settled, so its `ready` is the turn after the final HIRE.\n    """\n    tiles = shed_access_tiles(board_size)                  # NWSE: (4,4), (5,4), (4,5), (5,5)\n    spawn, ready, batches = {0: tuple(SPAWN)}, {}, []\n    k, turn = 0, 0\n    while k < hands:\n        n = min(per_turn, hands - k)\n        occ = {t: 0 for t in tiles}\n        occ[tuple(SPAWN)] = 1 + k                         # farmer home, every earlier hand walked back\n        for _ in range(n):\n            pick = min(occ.items(), key=lambda kv: (kv[1], tiles.index(kv[0])))[0]\n            occ[pick] += 1\n            k += 1\n            spawn[k], ready[k] = pick, turn + 1           # the HIRE settles at dusk of `turn`\n        batches.append((turn, n))\n        turn += 1\n    ready[0] = max(1, turn)\n    return batches, spawn, ready\n\n\ndef unit_for_cell(tile, board_size=BOARD_SIZE):\n    """The lowest unit index that spawns on `tile`.\n\n    Also the number of hands that must be hired that day to bring it into existence, since hands are\n    dismissed every dawn (`kaggriculture.py:849`) and unit `k` is the `k`-th hand.\n    """\n    for i, t in enumerate(spawn_order(board_size)):\n        if t == tuple(tile):\n            return i\n    raise ValueError(f"{tile} is not a spawn tile")\n\n\ndef land_purchases_for(tile, board_size=BOARD_SIZE):\n    """How many sequential BUY_LAND orders are needed before `tile` is unlocked.\n\n    `_do_buy_land` ignores its caller\'s wishes and unlocks `LAND_ORDER[n_already_bought]`, so\n    reaching SE costs all three purchases whether or not NE and SW are wanted.\n    """\n    q = quadrant_of(*tile, board_size=board_size)\n    if q == "NW":\n        return 0\n    return LAND_ORDER.index(q) + 1\n\n\nclass Script:\n    """A mutable action tape: `[T, U]` unit ops plus the per-turn market vector.\n\n    Deliberately plain arrays rather than a builder DSL. The optimiser mutates *plans*, expands them\n    through the routines below into one of these, and hands the arrays straight to the simulator --\n    the same arrays `scripts/build_script_submission.py` already turns into a verified submission.\n    """\n\n    #: `(day, unit) -> turns already claimed today`. Turn 0 of a day is the market order, so work\n    #: starts at 1 and a day holds `TURNS_PER_DAY - 1` ops.\n    #:\n    #: **This exists so two routines can share a unit.** Both `ranch()` and `grow()` used to lay their\n    #: day out from `d + 1` on the assumption that they owned the whole day, and `op()` assigns\n    #: `unit_op[t, u]` directly -- so calling both for one unit silently overwrote the first. Measured\n    #: on a 2-pen group plus a 4-tile block: 327 + 434 ops composed to 441, losing 320 of them, and the\n    #: herd stopped being fed on 29 of 30 days. Nothing raised and nothing reported it.\n    #:\n    #: That mattered because one chain = one unit capped the farm. Covering the leader\'s 14 pens plus\n    #: ~100 tile-plantings needed 14 chains, forcing unit 17, and the hire ladder resets every dawn:\n    #: 9 hands is $88/day but 17 is $4,180/day, i.e. $125,400 a season -- more than he banks in total.\n    #: He does it with twelve hands because his hands tend a pen *and* crop tiles on the same day.\n    #:\n    #: Claiming turns instead of assuming them makes an overfull day a **refusal the caller can count**\n    #: rather than an overwrite nobody can see, which is the same contract the land gate now honours.\n    def __init__(self, T=T_DEFAULT, U=U_DEFAULT):\n        self.T, self.U = T, U\n        self._claimed = {}\n        self._pos = {}\n        self.unit_op = np.zeros((T, U), np.int64)      # 0 == PASS\n        self.unit_crop = np.zeros((T, U), np.int64)\n        self.unit_item = np.zeros((T, U), np.int64)\n        self.unit_qty = np.zeros((T, U), np.int64)\n        self.sell = np.zeros((T, len(PRODUCTS)), np.int64)\n        self.buy_seed = np.zeros((T, len(CROPS)), np.int64)\n        self.buy_product = np.zeros((T, len(PRODUCTS)), np.int64)\n        self.buy_animal = np.zeros((T, len(ANIMAL_NAMES)), np.int64)\n        self.hire = np.zeros(T, np.int64)\n        self.buy_land = np.zeros(T, np.int64)\n\n    def arrays(self):\n        return {f: getattr(self, f) for f in\n                ("unit_op", "unit_crop", "unit_item", "unit_qty", "sell", "buy_seed",\n                 "buy_product", "buy_animal", "hire", "buy_land")}\n\n    def turns_left(self, day, unit):\n        """Work turns still free for `unit` on `day`. `TURNS_PER_DAY - 1` if nothing has claimed yet."""\n        return TURNS_PER_DAY - self._claimed.get((day, unit), 1)\n\n    def hold(self, day, unit, until):\n        """Burn `unit`\'s turns before `until` on `day`, so its first op lands exactly there.\n\n        A hand hired in the batch at turn `b` does not exist until turn `b + 1`, and an op written into\n        a turn before that is dropped by the harness before the environment sees it -- 7 ops on day 0\n        alone, including the PLANT that was the whole of `plants day 1: 16 against the tape\'s 17`.\n        The farmer uses this too: it must hold `(4,4)` until the last HIRE has settled, or the spawn\n        tiles `dawn_crew` predicts are wrong for every batch after it moves.\n        """\n        self._claimed[(day, unit)] = max(self._claimed.get((day, unit), 1), max(1, int(until)))\n\n    def claim(self, day, unit, n, what=""):\n        """Reserve `n` consecutive work turns for `unit` on `day` and return the first of them.\n\n        Raises when the day cannot hold them, which is the whole point: the caller then refuses the\n        chain and counts it, instead of writing over another routine\'s ops.\n        """\n        used = self._claimed.get((day, unit), 1)      # turn 0 is the market order\n        if used + n > TURNS_PER_DAY:\n            raise ValueError(\n                f"day {day} unit {unit}: {what or \'this routine\'} needs {n} turns but only "\n                f"{TURNS_PER_DAY - used} of {TURNS_PER_DAY - 1} remain (another routine on the same "\n                f"unit has claimed {used - 1}); use fewer tiles, a larger cadence, or another unit")\n        self._claimed[(day, unit)] = used + n\n        return day * TURNS_PER_DAY + used\n\n    def where(self, day, unit, default):\n        """Where `unit` stands partway through `day`, so a second routine walks from there.\n\n        Without this a combined chain is wrong even when it fits: `grow()` computes its walk from\n        `spawn_tile(unit)`, but after `ranch()` the unit is standing at a pen, so every MOVE lands\n        somewhere else and the ops that follow act on the wrong tile.\n        """\n        return self._pos.get((day, unit), tuple(default))\n\n    def stand(self, day, unit, pos):\n        """Record where `unit` finished its ops on `day`."""\n        self._pos[(day, unit)] = tuple(pos)\n\n    def op(self, t, u, name, item=None, qty=0, crop=None):\n        """Write one unit op. Out-of-range turns are dropped so a routine may run past the season."""\n        if not (0 <= t < self.T):\n            return\n        self.unit_op[t, u] = OP[name]\n        if item is not None:\n            self.unit_item[t, u] = ITEMS.index(item)\n            self.unit_qty[t, u] = qty\n        if crop is not None:\n            self.unit_crop[t, u] = CROPS.index(crop)\n\n\n# ---------------------------------------------------------------------------\n# Routines\n# ---------------------------------------------------------------------------\n\ndef ranch(script, animal, tile, start_day, land_day=0, sell=True, unit=None,\n          collect_fertilizer=True, sell_fertilizer=True, buy_land=True, buy_feed=True,\n          feed_every=None, build_every=1):\n    """Build pens on `tile`, stock them, and keep every animal fed for the rest of the season.\n\n    `tile` takes a single tile or a list of them. **A list is one chain, one unit, one slot** --\n    which is the point, because 1 pen = 1 slot meant five pens ate five of eight slots and left three\n    for crops, i.e. 12 crop tiles against the leader\'s 60-75. Strawberry alone is a $68,640 market\n    needing ~48 tiles, so those slots decide the whole farm.\n\n    The arithmetic. Per animal per day the loop is PICKUP, FEED, CARE, COLLECT_FERTILIZER, HARVEST =\n    five turns, and the four shed cells form a 2x2 block one unit walks in four moves:\n\n        4 moves + 4 animals x 5 turns = 24   just over the 23 available work turns\n        feeding every other day:  4 + 4 x 3.5 = 18   comfortable\n\n    `feed_every` is that cadence and defaults to whatever fits. It is safe for the same reason\n    alternate-day watering is: `jax_sim.py:1243` escapes an animal only after **two consecutive**\n    missed feeds, so a gap of one leaves the streak at 1 and the next feed resets it. The leader\n    feeds 319 times across 14 animals -- **22.8 each, not 30** -- so he is not feeding daily either.\n    CARE, COLLECT_FERTILIZER and HARVEST stay daily: they are cheap and none of them gates survival.\n\n    Emits the complete chain and nothing partial. There is deliberately no primitive that buys an\n    animal without also committing the feed loop that keeps it alive -- that combination is the\n    $300-$500 deterministic loss the search must never be able to propose.\n\n    **Everything here is a consequence of the dawn reset** (`kaggriculture.py:847-851`), which\n    dismisses every hand, teleports the farmer back to `(4,4)` and resets the hire ladder:\n\n    - Those hires repeat **every day**. The Fibonacci ladder resets daily, so three hands cost\n      $1+$1+$2 = $4/day, about $120 across a season.\n    - Carried inventory is auto-deposited at dusk, so the daily DROP is only needed to get product\n      into the shed in time for that day\'s sell order.\n    - **The walk repeats every day too**, which is the whole reason a pen may now sit anywhere. The\n      first version of this routine walked once, on the start day, and then fed thin air for the rest\n      of the season because dawn had teleported the unit home. The refusal that replaced it -- only\n      shed-access tiles, so no movement op was ever needed -- was a real safety property but it\n      capped the herd at four, one per quadrant, against the leader tape\'s **14** pens. Worse than\n      four in practice: cells three and four cost $3,000 and $7,000 of land against a $3,000 opening\n      bank, so substituting them scored $0 and 0/16 wins and the usable cap was two.\n\n      `grow()` already solved this the honest way -- re-walk from spawn every single day -- and that\n      is what happens here now. Two consequences follow from being off the shed, and both are\n      deliberate: a remote pen cannot DROP (the op tests shed-adjacency, so out in the field it is a\n      wasted turn), and its goods therefore only reach the shed at the dusk auto-drop, which pushes\n      its sell order to the **next dawn** rather than the same afternoon.\n\n    A pen still on a shed-access tile keeps the old zero-movement day exactly as it was, including\n    the same-day DROP and sell. That is why those four cells remain worth having and why the search\n    should still prefer them: they are strictly cheaper per day than anywhere else on the board.\n\n    `land_day` is separate from `start_day` because `_do_buy_land` silently no-ops when money is\n    short and the parcels cost $1,000/$2,000/$4,000 in sequence. Funding SE means earning first, so\n    when to buy land is a plan parameter, never a default.\n\n    **`collect_fertilizer` defaults on, and leaving it off was this routine\'s biggest omission.**\n    A fed animal sets `fertilizer_available` every night and COLLECT_FERTILIZER takes it for *no\n    action cost* (`plan.py:144`), so a day without one abandons a free unit. It is not a rounding\n    error: FERTILIZER is 23.1% of winner sales against milk\'s 9.1% (`shepherd.py:28`) and the\n    leaders banked ~$21,900 from 406 units. Every animal verdict this project produced before this\n    landed was measured on a milk-only cow, which is why the search kept concluding animals do not\n    pay. The collect is ordered **before** the DROP: fertilizer sits in `carried` until it is\n    dropped, so a collect after the drop would not reach the shed in time for that day\'s sell.\n    """\n    if animal not in ANIMALS:\n        raise ValueError(f"unknown animal {animal}")\n\n    # One tile or many. Normalised early so everything below is written against a list.\n    tiles = ([tuple(tile)] if isinstance(tile, tuple) and tile and isinstance(tile[0], int)\n             else [tuple(t) for t in tile])\n    if not tiles:\n        raise ValueError("ranch() needs at least one tile")\n    if len(set(tiles)) != len(tiles):\n        raise ValueError(f"duplicate pen tiles {tiles}")\n    # One quadrant, with the shed cells as the deliberate exception: they are the contiguous 2x2 block\n    # around the shed, one per quadrant by construction, and adjacent to each other -- `(4,4)` to\n    # `(5,4)` is a single EAST step. Refusing them would refuse the only pen group that needs no walk\n    # to the shed at all. Everything else routes inside one quadrant, as `grow()` does.\n    quads = {quadrant_of(*t) for t in tiles}\n    if len(quads) > 1 and not set(tiles) <= set(shed_access_tiles()):\n        raise ValueError(f"pens span quadrants {sorted(quads)}; one chain routes inside one quadrant")\n    tiles = serpentine(tiles)\n    tile = tiles[0]                      # the chain\'s anchor: its unit, its land, its walk\n    info = ANIMALS[animal]\n    a_idx = ANIMAL_NAMES.index(animal)\n    wheat = PRODUCTS.index("WHEAT")\n    prod_idx = PRODUCTS.index(info["product"])\n    fert_idx = PRODUCTS.index("FERTILIZER")\n    at_shed = tile in shed_access_tiles()\n    # A shed cell is worked by whoever wakes on it -- anyone else would have to walk to it for no\n    # reason. Anywhere else, the caller owns the choice and unit 0 is the free default, since the\n    # farmer costs no hire.\n    if unit is None:\n        u = unit_for_cell(tile) if at_shed else 0\n    else:\n        u = unit\n    # **Everything drawn from the shed must be drawn at `SPAWN`.** `ops.py:216` gates PICKUP, DROP\n    # and PLACE\'s shed branch on the tile being shed-access *and unlocked*, and three of the four\n    # shed tiles sit in quadrants that start LOCKED. A hand waking on `(5,4)` therefore picks up\n    # nothing at all -- no error, no cow, no wheat -- which is why the first remote pen banked $1,437\n    # against an empty farm\'s $3,000 and left the board with zero animals on it.\n    #\n    # A pen *on* a shed cell is the exception and keeps its zero-movement day: this routine buys the\n    # parcel its own quadrant needs, so by `land_day` the cell is unlocked and PICKUP works where the\n    # unit already stands. Walking such a cell out to `(4,4)` and back would cost two turns a day to\n    # solve a problem it does not have.\n    zero_movement = at_shed and tuple(spawn_tile(u)) == tile\n    to_spawn = [] if zero_movement else _path_ops(spawn_tile(u), SPAWN)\n    walk = [] if zero_movement else _path_ops(SPAWN, tile)\n\n    # --- land: every parcel up to and including this cell\'s quadrant ------\n    # **One per day, not one per turn.** These used to go out on turns `land_day*24 + 0,1,2`, so a\n    # cell in SE asked for $1,000 + $2,000 + $4,000 inside three turns against a $3,000 bank.\n    # `_do_buy_land` no-ops when money is short rather than refusing the plan, so the third order\n    # simply evaporated -- the farm never goes negative, it just quietly owns less land than the\n    # chain thinks it does, and the pen then walks until a LOCKED tile stops it and builds there.\n    #\n    # Spacing does not make $7,000 affordable; only earning does. What it buys is a schedule the\n    # search can actually express, so `land_day` chooses between plans that differ instead of\n    # between plans that all collapse to "whatever the opening bank covered". The leader tape is the\n    # shape to aim at: parcels on **day 7 and day 10**, spaced, and the third never bought at all.\n    #\n    # `buy_land=False` hands the schedule to the caller. A BUY_LAND order is a claim on a shared,\n    # ordered, farm-level resource -- `_do_buy_land` unlocks `LAND_ORDER[n_already_bought]` and\n    # ignores which quadrant was wanted -- so two chains each privately ordering "the parcels I need"\n    # over-buy as soon as their days differ. A pen on NE wanting day 7 and a pen on SW wanting day 10\n    # emitted orders on days 7, 10 and 11: three parcels, $7,000, when NE + SW is $3,000. `decode()`\n    # consolidates instead. Standalone callers keep the self-sufficient default.\n    if buy_land:\n        for k in range(land_purchases_for(tile)):\n            t = (land_day + k) * TURNS_PER_DAY\n            if 0 <= t < script.T:\n                script.buy_land[t] = 1\n\n    # --- the crew this cell needs, re-hired every dawn --------------------\n    # `maximum`, not `+=`: a cell needing 3 hands already provides units 1 and 2 for the nearer\n    # cells, so co-located routines must not each add their own.\n    for day in range(start_day, SEASON_DAYS):\n        t = day * TURNS_PER_DAY\n        if u > 0 and t < script.T:\n            script.hire[t] = max(int(script.hire[t]), u)\n\n    build_op = "BUILD_PASTURE" if info["structure"] == "PASTURE" else "BUILD_COOP"\n\n    # How often each animal is fed. `None` means "as often as the day allows": the survival rule is a\n    # two-strike one (`jax_sim.py:1243`, two consecutive missed feeds and the animal escapes), so a\n    # cadence of 2 is safe and halves both the turns and the wheat bill. One pen has room to feed\n    # daily; four do not, and rather than raise, the chain stretches the cadence until it fits.\n    if feed_every is None:\n        feed_every = 1 if len(tiles) <= 2 else 2\n    if feed_every < 1:\n        raise ValueError("feed_every must be at least 1")\n    if feed_every > 2:\n        raise ValueError("feed_every above 2 starves the herd: two missed feeds and it escapes")\n    if build_every < 1:\n        raise ValueError("build_every must be at least 1")\n    feed_shifts = [tiles[i::feed_every] for i in range(feed_every)]\n\n    def day_loop(day, setup):\n        """One day over the group. **One pen is built per day**, not all of them at once.\n\n        Building four pens on a single day needs 32 turns of a 24-turn day: each is BUILD, PICKUP,\n        PLACE, FEED, CARE, HARVEST on top of the walk. Staggering costs nothing -- an animal placed on\n        day `start_day + i` simply starts producing `i` days later -- and it matches cash flow, since\n        four animals is $1,600 against a $3,000 opening bank. The leader does the same: 14 pens with\n        `BUILD_PASTURE` spread across the season rather than clustered.\n        """\n        d = day * TURNS_PER_DAY\n        if d >= script.T:\n            return\n        # Pens built so far, and the one being raised today.\n        # **How fast the group fills, which is a cash decision and not a fact about pens.**\n        # This was `day - start_day`: one pen every single day, unconditionally. With four chains all\n        # starting on day 0 that buys four animals a day for four days -- $6,800 against a $3,000 bank --\n        # so most of them silently no-op while the feed and hire bills carry on. Measured: 16 ordered,\n        # 8 realised, bank $301 on day 10, and a faithful copy of the leader\'s shape banked $10,875\n        # where a three-cow plan banked $38,948.\n        #\n        # The leader\'s herd arrives 4 on day 0, then +2, +1, +4, +1, +2 through day 10. He is not\n        # building slowly because pens are slow; he is building at the rate his revenue funds.\n        # Pen `i` is raised on day `start_day + i*build_every`. A pen counts as *live* only from the day\n        # after it is placed, so `live` is the pens whose build day has strictly passed -- a **ceiling**\n        # division, not a floor. Flooring it left the day-0 animal out of `live` until day 3, so it went\n        # unfed for two consecutive nights, escaped, and the whole plan banked exactly $0.\n        elapsed = max(0, day - start_day)\n        n_live = min(len(tiles), -(-elapsed // build_every))\n        building = (tiles[n_live] if n_live < len(tiles) and elapsed % build_every == 0\n                    else None)\n        live = tiles[:n_live]\n        if not live and building is None:\n            return\n        # Feed only what exists. The shift index walks the live herd so each animal is reached at\n        # least every `feed_every` days.\n        feeding = [t for t in feed_shifts[(day - start_day) % feed_every] if t in live]\n        # **A pen must be fed on the day it is placed.** `consecutive_unfed` starts at 0 and ticks\n        # every night, so an animal placed on day D and first fed on D+2 escapes overnight on D+1 --\n        # before it has produced anything, for the full purchase price. Measured: four pens placed on\n        # consecutive days, zero alive at the bell.\n        if building is not None:\n            feeding = feeding + [building]\n        # Order feed a turn ahead of drawing it, so the market has resolved either way. One unit of\n        # wheat per animal actually being fed today, not per animal owned.\n        #\n        # `buy_feed=False` lives off the shed instead, which is the wheat -> animal -> fertilizer loop\n        # `production.py:53` calls the main structural reason to keep animals. It only closes if some\n        # `grow("WHEAT", ..., sell=False)` chain is stocking that shed: `pickup` takes by item index\n        # and does not care where the wheat came from, but `consecutive_unfed >= 2` escapes the animal\n        # for a deterministic $300-$500, so an empty shed is not a small mistake.\n        if buy_feed and feeding:\n            script.buy_product[d, wheat] += len(feeding)\n        if building is not None:\n            script.buy_animal[d, a_idx] += 1\n\n        # `(op_name, item, qty)`, built before any of it is written so the day\'s length can be\n        # checked. PICKUP only works next to the shed, so everything the unit must carry -- the\n        # animals on the build day, the wheat every day -- is drawn at spawn *before* the walk.\n        seq = []\n        pos = script.where(day, u, spawn_tile(u))\n        if not (zero_movement and len(tiles) == 1):\n            for m in _path_ops(pos, SPAWN):\n                seq.append((m, None, 0))\n            pos = tuple(SPAWN)\n        if building is not None:\n            seq.append(("PICKUP", animal, 1))\n        if feeding:\n            seq.append(("PICKUP", "WHEAT", len(feeding)))\n\n        for t_ in [t for t in tiles if t in live or t == building]:\n            for m in _path_ops(pos, t_):\n                seq.append((m, None, 0))\n            pos = t_\n            if t_ == building:\n                seq.append((build_op, None, 0))\n                seq.append(("PLACE", animal, 1))\n                seq.append(("FEED", None, 0))\n                # CARE on the build day too: `pending_care_bonus` accumulates while it waits, so the\n                # turn is banked rather than spent. No COLLECT_FERTILIZER or HARVEST -- both need an\n                # overnight tick the animal has not had yet.\n                seq.append(("CARE", None, 0))\n                continue\n            if t_ in feeding:\n                seq.append(("FEED", None, 0))\n            # CARE grants +1 yield on the next fed production day, and `pending_care_bonus` accumulates\n            # while it waits, capped at `max_held`. One turn a day for roughly double output; it is why\n            # CARE correlates +0.441 with money across 312 real leaderboard seats. Kept daily even on a\n            # non-feeding day: it is cheap and it does not gate survival.\n            seq.append(("CARE", None, 0))\n            if collect_fertilizer:\n                # `fertilizer_available` is set overnight for animals already alive, so a pen raised\n                # today has nothing to give -- which the `continue` above already skips.\n                seq.append(("COLLECT_FERTILIZER", None, 0))\n            seq.append(("HARVEST", None, 0))\n\n        if at_shed and pos in shed_access_tiles():\n            # Only worth a turn where it can succeed: DROP tests shed-adjacency, so out in the field\n            # it is a no-op and `_drop_to_shed` moves the goods at dusk regardless.\n            seq.append(("DROP", None, 0))\n\n        # Claim the turns rather than assume them, so a crop block sharing this unit cannot be\n        # overwritten -- and so an overfull day raises here instead of vanishing.\n        t = script.claim(day, u, len(seq),\n                         what=f"{len(tiles)} pen(s) at {tiles} from {spawn_tile(u)}")\n        for op_name, item, qty in seq:\n            script.op(t, u, op_name, item=item, qty=qty)\n            t += 1\n        script.stand(day, u, pos)\n\n        if sell:\n            # Over-requesting is safe: `_process_market` stops when the shed runs dry. Selling daily\n            # is the naive cadence -- it walks our own price down the glut curve -- and the timing is\n            # a plan parameter the search should own rather than something fixed here.\n            #\n            # A shed pen has already DROPped, so it can sell this afternoon. A remote pen\'s goods sit\n            # in `carried` until dusk, so its order has to wait for the next dawn or it quotes\n            # against a shed that does not hold them -- measured at exactly zero revenue in\n            # `test_grow_routine.py`.\n            t_sell = t + 1 if at_shed else (day + 1) * TURNS_PER_DAY\n            if t_sell < script.T:\n                # Scaled by the herd, not by one animal: a four-pen chain has four animals\' worth of\n                # product in the shed and an order for one animal\'s worth would leave three unsold.\n                script.sell[t_sell, prod_idx] += info["max_held"] * max(1, len(live))\n                if collect_fertilizer and sell_fertilizer:\n                    # **Selling and feeding it to plants are rival uses, and this used to be neither\n                    # a choice nor visible.** The pen sold every unit it collected while\n                    # `grow(fertilize=True)` bought units back off the same market -- the farm\n                    # trading with itself and paying the spread twice. FERTILIZER is 23.1% of winner\n                    # sales, so selling is not obviously wrong; a cow yields ~29 units a season and a\n                    # fertilized 4-tile block wants ~40, so feeding is not obviously wrong either.\n                    # It is a genuine trade-off and the search now owns it.\n                    script.sell[t_sell, fert_idx] += max(1, len(live))\n\n    for day in range(start_day, SEASON_DAYS):\n        day_loop(day, setup=(day == start_day))\n    return script\n\n\n# Which crops fertilizer is worth a turn on, derived from the measured season yields in\n# `kagg/economics/production.py` rather than restated here -- a second copy would drift, and the\n# whole point is that melon must never be fertilized by accident. Melon gains exactly nothing (12\n# units either way, its watering window already fills `max_yield`) while tomato and strawberry\n# double. FERTILIZE is active for the day it is spent plus two more, so a tile wants one every\n# third day and not daily.\ndef _crops_fertilizer_helps():\n    from kagg.economics import production as _P\n    return frozenset(c for c in CROPS\n                     if _P.TILE_YIELD_FERTILIZED[c] > _P.TILE_YIELD_PER_SEASON[c])\n\n\nFERTILIZER_HELPS = _crops_fertilizer_helps()\nFERTILIZER_ACTIVE_DAYS = 3\n\nCROP_TABLE = {\n    # `first`/`max_day` are ages in days since planting; `ongoing` crops are never cleared by a\n    # harvest and accrue to a lifetime cap instead. Mirrored from `kagg.sim.tiles`, pinned by tests.\n    # `interval` is the production cadence `_daily_refresh_plants` uses for an ongoing crop -- it was\n    # missing here, which meant nothing in the emitter could tell when a strawberry tile actually\n    # produces. Strawberry is every SECOND day, tomato every day.\n    "WHEAT":      {"first": 2,  "max_day": 4,  "max_yield": 6, "ongoing": False, "interval": 0},\n    "CARROT":     {"first": 2,  "max_day": 3,  "max_yield": 4, "ongoing": False, "interval": 0},\n    "TOMATO":     {"first": 8,  "max_day": 8,  "max_yield": 4, "ongoing": True,  "interval": 1},\n    "STRAWBERRY": {"first": 10, "max_day": 10, "max_yield": 4, "ongoing": True,  "interval": 2},\n    "MELON":      {"first": 10, "max_day": 12, "max_yield": 6, "ongoing": False, "interval": 0},\n}\n\n# `_DX`/`_DY` in `kagg.sim.ops`: NORTH is dy=-1, SOUTH dy=+1, EAST dx=+1, WEST dx=-1. So north is\n# *smaller* y, which agrees with `quadrant_of` calling y < half "N". Getting this backwards would\n# send every path the wrong way and is silent, because a blocked move is a no-op rather than an error.\ndef _axis_ops(src, dst):\n    """Movement ops `src` -> `dst`, X then Y. Safe only when the whole rectangle is unlocked."""\n    # **Y before X.** Measured against the leader\'s tape: of the 244 walks where our route was the\n    # right length but the wrong order, 220 moved north/south first and 18 east/west\n    # (`scripts/level2_route.py`). Same cost either way -- the board is a grid -- but matching the\n    # order is what lets a tape be compared to a tape at all, and the vertical-first rule also clears\n    # the locked-quadrant border sooner on this board\'s geometry.\n    ops = []\n    dx = dst[0] - src[0]\n    dy = dst[1] - src[1]\n    ops += ["SOUTH"] * dy if dy > 0 else ["NORTH"] * (-dy)\n    ops += ["EAST"] * dx if dx > 0 else ["WEST"] * (-dx)\n    return ops\n\n\ndef _walked_tiles(src, ops):\n    """The tiles a sequence of movement ops passes through, destination included."""\n    d = {"NORTH": (0, -1), "SOUTH": (0, 1), "EAST": (1, 0), "WEST": (-1, 0)}\n    x, y = src\n    out = []\n    for o in ops:\n        dx, dy = d[o]\n        x, y = x + dx, y + dy\n        out.append((x, y))\n    return out\n\n\ndef _bfs_ops(src, dst, parcels):\n    """Shortest movement ops from `src` to `dst` across tiles the farm owns, or None if unreachable.\n\n    Tie-break is the order of `_MOVE_ORDER` -- north/south before east/west -- which is the leader\'s\n    own rule, measured 220 to 18 on the walks where our route was the right length and the wrong\n    order.\n    """\n    from collections import deque\n    if src == dst:\n        return []\n    seen = {src}\n    q = deque([(src, [])])\n    while q:\n        (x, y), path = q.popleft()\n        for name, (dx, dy) in _MOVE_ORDER:\n            nxt = (x + dx, y + dy)\n            if nxt in seen:\n                continue\n            if not (0 <= nxt[0] < BOARD_SIZE and 0 <= nxt[1] < BOARD_SIZE):\n                continue\n            if land_purchases_for(nxt) > parcels:\n                continue\n            if nxt == dst:\n                return path + [name]\n            seen.add(nxt)\n            q.append((nxt, path + [name]))\n    return None\n\n\n#: North/south before east/west -- see `_axis_ops`.\n_MOVE_ORDER = (("NORTH", (0, -1)), ("SOUTH", (0, 1)), ("EAST", (1, 0)), ("WEST", (-1, 0)))\n\n\ndef _path_ops(src, dst, parcels=None):\n    """Movement ops walking `src` -> `dst`, routed through `SPAWN` so the walk never starts by\n    stepping into locked land.\n\n    The previous version went X-then-Y from wherever the unit stood, with the comment "any order\n    works inside one quadrant". That assumption breaks the moment the origin is in a *different*\n    quadrant from the destination, which is the normal case: hands spawn on the shed-access tiles,\n    and three of those four are in quadrants that start LOCKED.\n\n    `ops.py:86` ignores a move onto a LOCKED tile and the unit simply loses the turn -- silently.\n    So unit 2, spawning on `(4,5)` in SW, spent four turns pushing WEST into locked ground and then\n    walked north from where it had never left, arriving on a row it did not own. Measured on one\n    melon block: $5,402 against unit 0\'s $15,575.\n\n    `SPAWN` `(4,4)` is the one tile that is never locked, and every shed-access tile is one step from\n    it, so leaving via `SPAWN` is legal for any unit whose neighbour-to-`SPAWN` is unlocked. Unit 3 on\n    `(5,5)` is a genuine exception -- both its neighbours are locked on day 0 and it cannot move at\n    all until a parcel is bought. That is the game, not the routing, and the ops are emitted anyway\n    so the chain starts working the moment the land arrives.\n    """\n    src, dst = tuple(src), tuple(dst)\n    if src == dst:\n        return []\n    spawn = tuple(SPAWN)\n    # **Detour only when the direct route is actually blocked.** With `parcels` supplied the caller\n    # knows how much land the farm owns that day, so the walk can be checked rather than guessed.\n    #\n    # Guessing cost real distance: measured against the leader\'s tape, 194 of 410 routing mismatches\n    # were ours being LONGER than his, almost all of them this detour firing on a route that was\n    # never blocked (`scripts/level2_route.py`). Switching it off entirely took the router from\n    # 78.57% to 83.17% exact -- but off entirely is the bug this detour was added to fix, where unit\n    # 2 pushed WEST into locked ground for four turns and banked $5,402 against unit 0\'s $15,570.\n    # Checking is what gets both.\n    if parcels is not None:\n        direct = _axis_ops(src, dst)\n        if all(land_purchases_for(t) <= parcels for t in _walked_tiles(src, direct)):\n            return direct\n        # Direct route is blocked, so find the real shortest walk over the land we own rather than\n        # falling back on the SPAWN detour. Going via `(4,4)` is *a* legal route, not the short one:\n        # it added 2-8 steps on 119 walks the leader\'s tape did in fewer. BFS is exact and the board\n        # is 100 tiles, so the cost is irrelevant next to being wrong every day of the season.\n        found = _bfs_ops(src, dst, parcels)\n        if found is not None:\n            return found\n    # Only the *first* leg -- out of a shed-access tile -- can start in locked ground. Hops between\n    # tiles of a block start on land the chain already works, so they take the direct route. Sending\n    # those through SPAWN too would walk the unit home between every pair of adjacent tiles: 56 turns\n    # for a 4-tile block against a 24-turn day.\n    if src == spawn or src not in shed_access_tiles():\n        return _axis_ops(src, dst)\n    # Step to SPAWN first -- Y then X, because the shed tiles differ from SPAWN on one axis only.\n    out = []\n    dy = spawn[1] - src[1]\n    dx = spawn[0] - src[0]\n    out += ["SOUTH"] * dy if dy > 0 else ["NORTH"] * (-dy)\n    out += ["EAST"] * dx if dx > 0 else ["WEST"] * (-dx)\n    return out + _axis_ops(spawn, dst)\n\n\ndef serpentine(tiles):\n    """Order `tiles` so consecutive entries are adjacent where possible: rows, alternating direction.\n\n    A boustrophedon keeps the walk between tiles at one step instead of jumping back to the row start,\n    which matters because the turn budget is the binding constraint on how many tiles one unit can work.\n    """\n    rows = {}\n    for x, y in tiles:\n        rows.setdefault(y, []).append((x, y))\n    out = []\n    for i, y in enumerate(sorted(rows)):\n        row = sorted(rows[y], key=lambda t: t[0], reverse=bool(i % 2))\n        out += row\n    return out\n\n\ndef grow(script, crop_name, tiles, plant_day, harvest_age=None, land_day=0, sell=True, unit=0,\n         buy_fertilizer=True, buy_land=True, water_every=1,\n         fertilize=False):\n    """Plant, water and harvest a block of tiles, re-walking from spawn every day.\n\n    The crop analogue of `ranch()`, and structurally harder for one reason: `ranch()` is safe because\n    it binds to a shed-access tile and therefore **never emits a movement op**, so an edit cannot\n    invalidate later positions. There are only four such tiles and animals want them, so a crop block\n    lives on the other ~96 and this routine has to route. Everything below follows from that.\n\n    - **The walk repeats every day.** `_end_of_day` teleports every unit back to spawn at dawn\n      (`jax_sim.py:1228-1236`), so a routine that walks to the block once and then emits WATER for the\n      rest of the season waters the *spawn tile*. This is the same defect `ranch()` records fixing.\n    - **Water every day, both crop types.** `_daily_refresh_plants` kills any PLANT tile at\n      `consecutive_unwatered >= 2` regardless of `ONGOING`. The yield *bonus* only lands for\n      non-ongoing crops inside `[(max_day+1)//2, max_day]` (`jax_sim.py:632-636`), which tempts a\n      reader into skipping water for tomato and strawberry -- that kills them.\n    - **One-shot crops cycle, ongoing crops do not.** HARVEST sets a non-ongoing tile back to EMPTY\n      (`jax_sim.py:651`), so wheat can be replanted the next day and run several cycles a season.\n      An ongoing tile survives its harvest and keeps producing to a lifetime cap.\n    - **Ongoing crops are harvested every eligible day, deliberately.** Once `production_count` hits\n      `MAX_YIELD` the tile\'s `max_lifespan_step` is set and `_decay_plants` eats a unit every other\n      step, so accumulated yield rots. HARVEST is a silent no-op when nothing is ready\n      (`doable` requires `units > 0`), so harvesting daily costs one turn and makes decay unreachable\n      rather than merely unlikely.\n    - **Seeds are ordered at dawn and planted later the same day.** The atomic PLANT rule\n      (`jax_sim.py:565-582`) tests a turn\'s requests against seeds held at the *start* of that turn and\n      drops **every** request for a crop when demand exceeds supply, not just the excess. Ordering on\n      turn `d` and planting from `d+1` means the seeds have settled. `+=` is correct here, unlike the\n      `maximum` used for hires: two blocks of the same crop on one day need the sum of their seeds,\n      whereas they *share* the hands they hire.\n    - **No DROP, and therefore the sell waits for the next dawn.** `_end_of_day` calls `_drop_to_shed`\n      unconditionally (`jax_sim.py:1230`), so a harvest reaches the shed at dusk without a walk back.\n      But it is in `carried` until then, so a SELL on the harvest day itself quotes against a shed that\n      does not hold the crop. `ranch()` gets away with a same-day sell only because it stands on a shed\n      tile and emits DROP first; out in a field, DROP cannot reach the shed. Measured: selling same-day\n      banked **zero revenue on every crop**, losing exactly the seed cost\n      (`tests/test_crop_routine.py::test_a_crop_routine_pays_for_itself`).\n\n    Raises rather than truncates when a day\'s work will not fit in 24 turns -- a silently overflowing\n    day would spill ops into the next dawn, where the unit has been teleported away.\n    """\n    if crop_name not in CROP_TABLE:\n        raise ValueError(f"unknown crop {crop_name}")\n    tiles = [tuple(t) for t in tiles]\n    if not tiles:\n        raise ValueError("grow() needs at least one tile")\n    quads = {quadrant_of(*t) for t in tiles}\n    if len(quads) > 1:\n        raise ValueError(f"block spans quadrants {sorted(quads)}; v1 routes inside one quadrant only")\n\n    info = CROP_TABLE[crop_name]\n    c_idx = CROPS.index(crop_name)\n    prod_idx = PRODUCTS.index(crop_name)\n    ordered = serpentine(tiles)\n    if water_every < 1:\n        raise ValueError("water_every must be at least 1")\n    # **How often a tile is visited, which sets how much land one unit can hold.**\n    #\n    # Watering every tile every day costs about three turns per tile -- the WATER plus the walk -- so a\n    # 24-turn day caps a block at four. Six raises. That single default is why our farm is 12-16 crop\n    # tiles while the leader works 60-75.\n    #\n    # The game does not require it. Death needs **two consecutive** dry days (`tiles.py:157`), so one\n    # dry day leaves the streak at 1 and the next visit resets it; and base production never tests\n    # watering at all (`tiles.py:178` -- watering gates only the fertilizer doubling). So `water_every=2`\n    # visits half the tiles each day and legally holds **eight**.\n    #\n    # It is opt-in per chain because it is not universally good. Measured, one unit, whole season:\n    # strawberry 4 daily $6,182 -> 8 alternate $9,395 (**+52%**), melon 4 daily $15,575 -> 8 alternate\n    # $11,167 (**-28%**). Strawberry is ongoing and produces on a fixed interval, so it does not care\n    # which days it is visited. Melon is one-shot with a window that shuts at `max_day` 12, and a\n    # missed visit forfeits the harvest to `decay_plants`. Wheat is worse still at 2-4 days.\n    #\n    # Why it matters: strawberry is the largest market in the game -- drain 572 at base 120 is $68,640\n    # against melon\'s 140 at 250 for $35,000 -- and filling it needs ~48 tiles. At four tiles a unit\n    # that is twelve slots and out of reach; at eight it is six.\n    shifts = [ordered[i::water_every] for i in range(water_every)]\n    # Default to the top of the bonus-water window: the most yield from one planting. A caller wanting\n    # more cycles of a fast crop passes a smaller age explicitly -- that trade is a plan parameter.\n    age_to_harvest = info["max_day"] if harvest_age is None else harvest_age\n    if age_to_harvest < info["first"]:\n        raise ValueError(f"{crop_name} cannot be harvested before age {info[\'first\']}")\n\n    # One parcel per day, for the reason spelled out in `ranch()`, and skippable for the same reason:\n    # `decode()` owns the farm-level schedule when more than one chain wants land.\n    if buy_land:\n        for k in range(land_purchases_for(ordered[0])):\n            t = (land_day + k) * TURNS_PER_DAY\n            if 0 <= t < script.T:\n                script.buy_land[t] = 1\n\n    # `maximum`, not `+=`: co-located routines share the crew, exactly as in `ranch()`.\n    for day in range(plant_day, SEASON_DAYS):\n        t = day * TURNS_PER_DAY\n        if unit > 0 and t < script.T:\n            script.hire[t] = max(int(script.hire[t]), unit)\n\n    # Per-tile planting day, so one-shot crops can start a fresh cycle after each harvest.\n    planted = {t: None for t in ordered}\n    # Last day each tile\'s fertilizer is still active, so a tile is re-dosed every third day rather\n    # than every day. `fertilize` is opt-in: turning it on by default would silently re-price every\n    # measurement taken before it existed.\n    fertilized_until = {t: -1 for t in ordered}\n    # Has this tile already carried a crop of ours? Only then can it have sat EMPTY long enough to\n    # catch a weed, and only then is a DIG before the next PLANT worth its turn.\n    harvested = {t: False for t in ordered}\n    fertilizing = fertilize and crop_name in FERTILIZER_HELPS\n\n    for day in range(plant_day, SEASON_DAYS):\n        d = day * TURNS_PER_DAY\n        # `Script.op` drops out-of-range turns so a routine may run past the season; the market arrays\n        # are raw indexing and must honour the same contract explicitly.\n        if d >= script.T:\n            break\n        jobs = {}\n        dig_tiles = []\n        # Which tiles this unit reaches today. With `water_every=1` this is the whole block, exactly as\n        # before; with 2 it alternates halves, so every tile is visited every second day.\n        today = shifts[(day - plant_day) % water_every]\n        for tile in today:\n            p = planted[tile]\n            if p is None:\n                # **WATER on the planting day, not from the next one.** A seedling is already at\n                # `consecutive_unwatered = 1`, so skipping today\'s water lets dusk take it to 2 and\n                # `_daily_refresh_plants` turns it into a WEED on its first night -- after which WATER\n                # (needs `kind == PLANT`) and PLANT (needs `EMPTY`) both silently no-op forever while\n                # the routine keeps buying seeds. Traced in `data/logs/crop_trace.log`.\n                #\n                # **DIG first, but only on a tile we have already cropped once.** `_spawn_weeds` fires\n                # at 0.005 per EMPTY tile per turn, so ground that has sat idle for a day carries\n                # `1 - 0.995**24` ~ 11% of being a WEED -- and PLANT needs EMPTY, so a weed there\n                # kills the tile for the rest of the season, silently, while the seed orders continue.\n                #\n                # An open-loop tape cannot see which tile weeded, and it does not need to: `dig()`\n                # acts only on WEED, PLANT or an empty structure (`ops.py:156`), so on clean ground it\n                # is a no-op costing one turn. That is insurance, and it is what the leader does --\n                # all 23 of his inspectable digs land on an EMPTY tile and nine of the first twelve\n                # are immediately followed by PLANT, WATER\n                # (`docs/new_leader_somewhere_after_2026-08-05.md`).\n                #\n                # Never before a *first* plant: that ground was never idle under us, so the turn would\n                # be pure loss. And it is **dropped rather than raising** when the day is full, for\n                # the same reason the fertilizing is: a block that fits without insurance must keep\n                # fitting, or adding the option would silently shrink the search\'s reachable board.\n                # A 4-tile replant day needs 25 of 24 turns with four digs, so this matters.\n                if harvested[tile]:\n                    dig_tiles.append(tile)\n                jobs[tile] = ["PLANT", "WATER"]\n            else:\n                age = day - p\n                if info["ongoing"]:\n                    jobs[tile] = ["WATER"] + (["HARVEST"] if age >= info["first"] else [])\n                elif age >= age_to_harvest:\n                    # Water first: it still lands inside the bonus window on the harvest day itself.\n                    jobs[tile] = ["WATER", "HARVEST"]\n                else:\n                    jobs[tile] = ["WATER"]\n\n        n_plant = sum(1 for v in jobs.values() if "PLANT" in v)\n        if n_plant:\n            script.buy_seed[d, c_idx] += n_plant\n\n        fert_tiles = []\n        if fertilizing:\n            for tile in today:\n                if fertilized_until[tile] >= day:\n                    continue                    # still active from an earlier application\n                if "HARVEST" in jobs[tile] and not info["ongoing"]:\n                    continue                    # cleared to EMPTY tonight, so the bonus never lands\n                fert_tiles.append(tile)\n\n        def _sequence(fert, digs=()):\n            """The day\'s ops as `(op_name, tile)`, from spawn. Built before writing so the length\n            can be checked -- adding fertilizer or a dig must never turn a legal block into a\n            raising one."""\n            seq = []\n            pos = script.where(day, unit, spawn_tile(unit))\n            if fert:\n                # **Drawn on `SPAWN`, not wherever this unit woke up.** PICKUP needs a shed-access\n                # tile that is *unlocked* (`ops.py:216`) and only `(4,4)` is always both, so a hand\n                # spawning in NE or SW picked up nothing and every FERTILIZE after it no-opped. The\n                # step costs nothing in turns: `_path_ops` routes out through `SPAWN` anyway.\n                for op_name in _path_ops(pos, SPAWN):\n                    seq.append((op_name, None))\n                pos = tuple(SPAWN)\n                seq.append(("PICKUP", None))\n            for tile in today:\n                for op_name in _path_ops(pos, tile):\n                    seq.append((op_name, None))\n                pos = tile\n                if tile in digs:\n                    # Immediately before the PLANT, which is the only ordering that helps: it clears\n                    # a weed that would otherwise make the PLANT a silent no-op.\n                    seq.append(("DIG", tile))\n                for op_name in jobs[tile]:\n                    seq.append((op_name, tile))\n                if tile in fert:\n                    seq.append(("FERTILIZE", tile))\n            return seq\n\n        # Against the turns *still free* on this unit today, not against a whole empty day: a pen group\n        # sharing the unit has already claimed some, and measuring the optional extras against the full\n        # day would overflow the claim and raise where dropping the insurance would have fitted.\n        budget = script.turns_left(day, unit)\n        seq = _sequence(fert_tiles, dig_tiles)\n        if dig_tiles and len(seq) > budget:\n            # Insurance is the first thing to go: it protects an 11% risk, while overflowing the day\n            # pushes work past the dawn teleport and loses it outright.\n            dig_tiles = []\n            seq = _sequence(fert_tiles, dig_tiles)\n        if fert_tiles and len(seq) > budget:\n            # Drop the fertilizing rather than raise. A block that fits unfertilized must keep\n            # fitting, or switching the option on would silently shrink the search\'s reachable board.\n            fert_tiles = []\n            seq = _sequence(fert_tiles, dig_tiles)\n\n        if fert_tiles and buy_fertilizer:\n            # **Order it, exactly as the seeds above are ordered.** The PICKUP draws from the shed\n            # and nothing else ever stocks it: `ranch()` sells its collected fertilizer the same day,\n            # so even a farm with four cows hands the crop unit an empty shed. Without this the\n            # FERTILIZE ops are emitted, counted, and refused by `ops.py:378` for want of a carried\n            # unit -- which is why `fertilize=1` and `fertilize=0` scored identically to the dollar\n            # in all eight slots of the $64,146 genome.\n            script.buy_product[d, PRODUCTS.index("FERTILIZER")] += len(fert_tiles)\n\n        # Claim, for the reason spelled out on `Script.claim`: a pen group may share this unit, and\n        # writing from `d + 1` regardless is what silently deleted 42% of a combined chain\'s ops.\n        t = script.claim(day, unit, len(seq),\n                         what=f"{len(today)} of {len(ordered)} tiles")\n        for op_name, _tile in seq:\n            if op_name == "PICKUP":\n                script.op(t, unit, "PICKUP", item="FERTILIZER", qty=len(fert_tiles))\n            else:\n                script.op(t, unit, op_name, crop=crop_name if op_name == "PLANT" else None)\n            t += 1\n        if today:\n            script.stand(day, unit, today[-1])\n        for tile in fert_tiles:\n            fertilized_until[tile] = day + FERTILIZER_ACTIVE_DAYS - 1\n\n        if sell and any("HARVEST" in v for v in jobs.values()):\n            # **Next dawn, not this evening.** The harvest is in `carried` until `_drop_to_shed` runs at\n            # dusk, so a sell on this day finds an empty shed. Over-requesting is safe --\n            # `_process_market` stops when the shed runs dry -- and the cadence itself is a plan\n            # parameter, not a fact about the crop.\n            n_harvested = sum(1 for v in jobs.values() if "HARVEST" in v)\n            t_sell = (day + 1) * TURNS_PER_DAY\n            if t_sell < script.T:\n                script.sell[t_sell, prod_idx] += info["max_yield"] * n_harvested\n\n        for tile in today:\n            if "HARVEST" in jobs[tile]:\n                # Records that this ground has been cropped, so its next PLANT gets a DIG first.\n                harvested[tile] = True\n            if "PLANT" in jobs[tile]:\n                planted[tile] = day\n            elif "HARVEST" in jobs[tile] and not info["ongoing"]:\n                planted[tile] = None       # cleared to EMPTY, so it replants next day\n\n    return script\n\n\n# ---------------------------------------------------------------------------\n# Inspection helpers, used by the tests to check the tape rather than trust it\n# ---------------------------------------------------------------------------\n\ndef _turns_with(script, unit, op_name):\n    return np.flatnonzero(np.asarray(script.unit_op)[:, unit] == OP[op_name])\n\n\ndef feed_days(script, unit):\n    return {int(t) // TURNS_PER_DAY for t in _turns_with(script, unit, "FEED")}\n\n\ndef place_day(script, unit):\n    ts = _turns_with(script, unit, "PLACE")\n    return int(ts[0]) // TURNS_PER_DAY if len(ts) else None\n\n\ndef build_turn(script, unit):\n    ops = np.asarray(script.unit_op)[:, unit]\n    ts = np.flatnonzero((ops == OP["BUILD_PASTURE"]) | (ops == OP["BUILD_COOP"]))\n    return int(ts[0]) if len(ts) else None\n'
_SOURCES['kagg.search.router'] = '"""Layer 3 as the optimisation problem it actually is, solved as one thing instead of five patches.\n\nNamed properly, the daily problem is a **Team Orienteering Problem on a grid**: a fixed depot (the\nfour shed-access cells), `k` vehicles (the farmer and its hands), a hard per-vehicle budget of\n`TURNS_PER_DAY - 1` turns, mandatory nodes (FEED -- two missed days and the animal is gone outright,\n`kaggriculture.py:786`), optional prize-bearing nodes (WATER, HARVEST, CARE, FERTILIZE), and nodes\nwhose service requires an item drawn at the depot first. Across the season, with water every second\nday and feed every day, it is a Periodic VRP. Choosing *which* tiles to work is a separate, static\np-median problem, solved once per land unlock rather than per turn.\n\nThis matters because it says what the previous five attempts were missing. Every one of them keyed\nthe choice on a **priority rank** -- `(rank, distance)`, then `(distance, rank)`, then a rank table\nreordered by hand -- and the standard TOP heuristic is neither. It is\n\n    insert the node maximising  prize / marginal insertion cost\n\nso a rank table is the numerator of a fraction that was never written down. That is why reweighting\nit always made things worse: `(rank, d)` sent twelve hands across the board for the highest-priority\ntask anywhere at ~7 move turns per work turn; `(d, rank)` banked $809 because the nearest task is\nnever the important one. Both are degenerate limits of the same missing ratio.\n\nIt also says ES and RL are the wrong tools here, and not for want of ambition: the objective is\ndeterministic, exact and costs microseconds; the instance is ~40 nodes and ≤12 vehicles; Manhattan\ndistance on a grid admits no metric pathologies. Learning an approximation of something computable\nexactly is strictly worse. Same conclusion this project already reached at the schedule layer.\n\nThree things the reference gives us that change the shape of the problem, all read off the source\nrather than assumed:\n\n- **PICKUP has no capacity limit.** `n = min(n, available)` then `_inv_add(inv, item, n)`\n  (`kaggriculture.py:340`). One turn draws the whole day\'s feed, so a unit servicing fourteen pens\n  needs **one** depot stop, not fourteen. `schedule_agent` drew one wheat at a time.\n- **A tile is one stop with several ops.** An animal tile wants FEED, CARE, COLLECT_FERTILIZER and\n  HARVEST -- four turns, no movement between them. So the routing nodes are *tiles*, and a tile\'s\n  service time is however many ops it wants. This is why pens on the shed cells are nearly free.\n- **A one-shot crop\'s yield comes only from WATER inside its window**, and `FERTILIZE` is read at\n  WATER time (`bonus = 2 if tile["fertilized_until_day"] >= day else 1`), so within a visit\n  FERTILIZE must be emitted *before* WATER. An ongoing crop\'s production needs no water at all --\n  water only resets `consecutive_unwatered` and enables the fertilizer bonus -- which is the derived\n  reason "water every tile every day" measured at **-$18,569**.\n\n## The prize table is derived, not tuned\n\nEvery prize below is a marginal dollar figure computed from the reference\'s own mechanics, which is\nwhat makes the ratio meaningful. The interesting ones:\n\n    HARVEST          yield_units x base price                                exact\n    WATER  one-shot  base price, doubled if fertilized, 0 at max_yield       exact: one water = one unit\n    WATER  survival  the tile\'s whole remaining value                        consecutive_unwatered >= 1\n    WATER  ongoing   0 unless fertilized into a production day               water does not produce\n    CARE             base price of the product                               +1 unit next production\n    FEED   hungry    animal cost + remaining production                      mandatory\n    COLLECT_FERT.    100                                                     FERTILIZER base price\n    FERTILIZE        the doubling it will actually buy, over 3 days\n\n`CARE` coming out near $160 for one turn on a cow is not a thumb on the scale -- `pending_care_bonus`\naccrues on every cared-and-fed day and is consumed as extra units on the next production day\n(`kaggriculture.py:795-799`). It is genuinely one of the best ops in the game, which is what the\nleaderboard correlation already said (CARE +0.441 against PLANT -0.358) and what nothing in this\nproject had acted on.\n"""\n\nimport collections\n\nfrom . import routines as R\n\nTPD = R.TURNS_PER_DAY\nWORK_TURNS = TPD - 1\nSHED = tuple(R.shed_access_tiles())\nSHED_SET = frozenset(SHED)\nCROP = R.CROP_TABLE\nANIMALS = R.ANIMALS\n\n#: The reference\'s `MARKET` bases (`kaggriculture.py:25-49`). Prices move with inventory during the\n#: season, but the *ranking* is what the router needs and that is stable, so the bases are the right\n#: constant to plan against rather than the live quote.\nBASE_PRICE = {"WHEAT": 25, "CARROT": 35, "TOMATO": 60, "STRAWBERRY": 120, "MELON": 250,\n              "EGG": 50, "MILK": 160, "WOOL": 200, "FERTILIZER": 100}\n\n#: `crop_ops` used `BASE_PRICE["FERTILIZER"]` (100) as fertilizing\'s cost, but nobody pays that: it is\n#: the market\'s I0 equilibrium price, and the fertilizer we actually SELL realises a mean of $53 a unit\n#: (`scripts/the_market_ledger.py`, seed 11: 239 units for $12,601). We also COLLECT far more of it than\n#: we spend -- 314 fertilizer-days collected against 62-67 FERTILIZE ops a season -- so almost every unit\n#: we hold is heading for a SELL order anyway, and the true opportunity cost of routing one into a tile\n#: instead is what it would have sold for, not the sticker price. Measured, not tuned: it is the mean\n#: realised sale price on the seed this project measures against.\nFERTILIZER_COST = 53\n\n#: Prize for a node that must be served or something dies. Large enough to dominate any ordinary\n#: prize, finite so that two mandatory nodes still order by cost between themselves.\nMANDATORY = 100_000\n\n#: The reference\'s seed prices (`CROPS[...]["seed"]`). Seeds are NOT held in the shed or in a unit\'s\n#: inventory -- `private["seeds"]` is consumed directly by PLANT -- which is why PLANT never generates\n#: a depot stop no matter that it carries an item name.\nSEED_COST = {"WHEAT": 10, "CARROT": 20, "TOMATO": 50, "STRAWBERRY": 100, "MELON": 80}\n\n#: Ops whose item really is drawn at the shed. `BUILD` is here because the unit may as well carry the\n#: animal on the same trip and PLACE it the turn after the pen goes up.\nDRAWN = ("FEED", "FERTILIZE", "PLACE", "BUILD")\n\n\ndef dist(a, b):\n    return abs(a[0] - b[0]) + abs(a[1] - b[1])\n\n\n# ---------------------------------------------------------------------------------------------\n# placement: the static half of the problem, solved once per land unlock rather than per turn\n# ---------------------------------------------------------------------------------------------\n\n#: Quadrants in the order the reference sells them (`LAND_ORDER` at [1000, 2000, 4000]), NW being free.\n_QUAD_ORDER = ("NW",) + tuple(R.LAND_ORDER)\n\n\ndef field_order(unlocked, board_size=R.BOARD_SIZE):\n    """Every workable tile we own, in the order it should be taken. Deterministic, no board state.\n\n    Choosing WHICH tiles to farm is a facility-location problem, not a per-turn one: the set is worked\n    ~20 times a season, so its shape is paid for over and over while the choice itself is made once.\n    `_nearest_empty` scored one tile at a time on `(adjacency, distance)`, which grows a SNAKE out from\n    whichever tile happened to be planted first -- locally adjacent at every step and globally a long\n    thin thing to walk.\n\n    A compact block is the right shape, and on a grid the right visiting order for a block is a\n    **boustrophedon sweep**: rows taken in alternating direction, so consecutive tiles are always\n    adjacent and covering `n` tiles costs `n - 1` steps. Anchoring each quadrant\'s sweep at its\n    shed-access corner means the first tiles taken are the ones nearest the depot, so a farm that only\n    ever fills half its ground automatically fills the near half.\n\n    The four shed-access cells are left out: they are worth more as pens, where FEED, CARE,\n    COLLECT_FERTILIZER, PICKUP and DROP all happen without a single move.\n    """\n    half = board_size // 2\n    out = []\n    for quad in _QUAD_ORDER:\n        if quad not in unlocked:\n            continue\n        xs = range(0, half) if quad.endswith("W") else range(half, board_size)\n        ys = range(0, half) if quad.startswith("N") else range(half, board_size)\n        # Sweep away from the shed: rows nearest the middle first, and each row swept from the\n        # middle outwards, alternating so the end of one row touches the start of the next.\n        rows = sorted(ys, key=lambda y: -y if quad.startswith("N") else y)\n        cols = sorted(xs, key=lambda x: -x if quad.endswith("W") else x)\n        for i, y in enumerate(rows):\n            for x in (cols if i % 2 == 0 else cols[::-1]):\n                if (x, y) not in SHED_SET:\n                    out.append((x, y))\n    return out\n\n\n# ---------------------------------------------------------------------------------------------\n# prizes\n# ---------------------------------------------------------------------------------------------\n\ndef _crop_remaining(cell, day):\n    """Dollar value still recoverable from a planted tile, used as the cost of letting it weed."""\n    info = CROP[cell["crop"]]\n    price = BASE_PRICE[cell["crop"]]\n    if not info["ongoing"]:\n        age = day - cell["planted_day"]\n        window_end = info["max_day"]\n        if age > window_end:\n            return cell.get("yield_units", 0) * price\n        waters_left = window_end - max(age, (window_end + 1) // 2) + 1\n        room = info["max_yield"] - cell.get("yield_units", 0)\n        return max(0, min(room, waters_left)) * price\n    # ongoing: one unit per production, `interval` days apart, `max_yield` productions in total\n    age = day - cell["planted_day"]\n    done = 0 if age < info["first"] else (age - info["first"]) // info["interval"] + 1\n    left = max(0, info["max_yield"] - done)\n    days_left = R.SEASON_DAYS - 1 - day\n    return min(left, days_left // max(1, info["interval"]) + 1) * price\n\n\ndef _animal_remaining(cell, day):\n    a = ANIMALS[cell["animal"]]\n    price = BASE_PRICE[a["product"]]\n    age = day - cell["placed_day"]\n    days_left = R.SEASON_DAYS - 1 - day\n    if age < a["first_yield_day"]:\n        days_left -= a["first_yield_day"] - age\n    return max(0, days_left) // a["interval"] * price\n\n\ndef crop_ops(cell, day, have_fertilizer):\n    """`[(op, item, prize)]` worth doing on a planted tile today, in the order they must be emitted.\n\n    FERTILIZE precedes WATER because WATER reads `fertilized_until_day` at the moment it runs.\n    """\n    info = CROP[cell["crop"]]\n    price = BASE_PRICE[cell["crop"]]\n    age = day - cell["planted_day"]\n    held = cell.get("yield_units", 0)\n    room = info["max_yield"] - held\n    fertilized = cell.get("fertilized_until_day", -1) >= day\n    out = []\n\n    if not info["ongoing"]:\n        in_window = (info["max_day"] + 1) // 2 <= age <= info["max_day"]\n        # A one-shot water inside the window IS the yield: one unit, two if fertilized. So a melon\n        # water is worth $250 -- the single highest-value op available -- and a melon water outside\n        # the window is worth nothing at all.\n        if in_window and room > 0:\n            # Worth fertilizing only if the remaining window cannot fill the tile on plain waters.\n            waters_left = info["max_day"] - age + 1\n            if (not fertilized and have_fertilizer and waters_left < room\n                    and cell.get("fertilized_until_day", -1) < day):\n                gain = min(room, waters_left * 2) - min(room, waters_left)\n                if gain * price > FERTILIZER_COST:\n                    out.append(("FERTILIZE", "FERTILIZER", gain * price))\n                    fertilized = True\n            if not cell["watered_today"]:\n                out.append(("WATER", None, price * (2 if fertilized else 1)))\n        elif not cell["watered_today"] and cell["consecutive_unwatered"] >= 1:\n            # Outside the window water buys nothing but survival, and it is only needed on the day\n            # the tile would otherwise weed. This is the every-SECOND-day rule, derived. It is\n            #\n            # It is NOT mandatory, though the loss is real and permanent. Promoting it into the\n            # mandatory pass alongside fourteen pens was measured over twelve seeds at **-$2,804**:\n            # harvests recovered 296 -> 318 and feeding fell straight back, 321 -> 301, because a pass\n            # that contains everything cannot triage. The prize below is already the tile\'s whole\n            # remaining value, which is the honest number; it simply has to compete.\n            out.append(("WATER", None, _crop_remaining(cell, day)))\n    else:\n        # An ongoing crop produces at dawn regardless of water. Water is survival, plus the\n        # fertilizer bonus on a production day. Watering it on any other day is pure walk.\n        produces_tomorrow = (age + 1 >= info["first"]\n                             and (age + 1 - info["first"]) % info["interval"] == 0)\n        if not cell["watered_today"]:\n            if cell["consecutive_unwatered"] >= 1:\n                out.append(("WATER", None, _crop_remaining(cell, day)))\n            elif fertilized and produces_tomorrow and room > 0:\n                out.append(("WATER", None, price))\n        if (produces_tomorrow and not fertilized and have_fertilizer and room > 1\n                and price > FERTILIZER_COST):\n            out.append(("FERTILIZE", "FERTILIZER", price))\n\n    if held > 0 and age >= info["first"] and (info["ongoing"] or _one_shot_is_finished(info, age, room)):\n        out.append(("HARVEST", None, held * price))\n    return out\n\n\ndef _one_shot_is_finished(info, age, room):\n    """Has a one-shot crop stopped being able to grow? Only then is harvesting it free money.\n\n    HARVEST sets the tile to `None` (`kaggriculture.py:409`), so on a one-shot crop it is not a\n    collection, it is a demolition. Offering it at `held * price` the moment the first unit lands made\n    an age-3 wheat worth $25 to harvest against $25 for another water -- and since both ops hang off\n    the SAME node, the visit did both: watered to two units, then deleted a tile that had a third\n    water still owed to it. Seed 11 lost five crop tiles on day 3 that way.\n\n    Nothing is forfeited once the window has shut (no further water can add a unit) or the tile is\n    already at `max_yield`. Waiting past that only feeds the rot at `max_lifespan_step`.\n    """\n    return age >= info["max_day"] or room <= 0\n\n\ndef animal_ops(cell, day, have_wheat):\n    """`[(op, item, prize)]` for a stocked pen. FEED is mandatory the day after a missed feed."""\n    a = ANIMALS[cell["animal"]]\n    price = BASE_PRICE[a["product"]]\n    out = []\n    fed = cell["fed_today"]\n    if not fed and have_wheat:\n        hungry = cell.get("consecutive_unfed", 0) >= 1\n        # **Every feed is mandatory, not only the one that prevents an escape.** Priced at one unit of\n        # product a cow\'s FEED was $160 for a turn against a melon water\'s $250, so on any tight day the\n        # ratio rule skipped the pen -- and skipping it forfeits the day\'s production AND the care\n        # bonus, since `pending_care_bonus` is only paid out on a day the animal is also fed. Across 312\n        # leaderboard seats FEED correlates +0.452 with final money and WATER -0.276, so the ranking was\n        # inverted against the only op-level evidence we have.\n        #\n        # A hungry day is still worth more than a healthy one -- the animal itself is on the line -- so\n        # the two stay ordered above the shared mandatory floor.\n        prize = MANDATORY + price + ((a["cost"] + _animal_remaining(cell, day)) if hungry else 0)\n        out.append(("FEED", "WHEAT", prize))\n        fed = True\n    if not cell["cared_today"] and fed:\n        # `pending_care_bonus` is only consumed on a day the animal is ALSO fed, so an uncared or\n        # unfed pen banks nothing. One care = one extra unit of product on the next production day.\n        out.append(("CARE", None, price))\n    if cell.get("fertilizer_available"):\n        out.append(("COLLECT_FERTILIZER", None, BASE_PRICE["FERTILIZER"]))\n    if cell.get("yield_units", 0) > 0:\n        out.append(("HARVEST", None, cell["yield_units"] * price))\n    return out\n\n\ndef plant_prize(crop, day):\n    """What a fresh planting is worth, or 0 if the season cannot finish it.\n\n    A melon needs to reach age 12 and a wheat age 4, so late in the season most of the crop table is\n    literally worth nothing and the ground is better left empty than seeded.\n    """\n    info = CROP[crop]\n    price = BASE_PRICE[crop]\n    days_left = R.SEASON_DAYS - 1 - day\n    if not info["ongoing"]:\n        if days_left < info["first"]:\n            return 0\n        window_end = min(info["max_day"], days_left)\n        waters = window_end - (info["max_day"] + 1) // 2 + 1\n        return max(0, min(info["max_yield"], waters)) * price\n    if days_left < info["first"]:\n        return 0\n    prods = (days_left - info["first"]) // info["interval"] + 1\n    return min(info["max_yield"], prods) * price\n\n\n# ---------------------------------------------------------------------------------------------\n# nodes\n# ---------------------------------------------------------------------------------------------\n\nclass Node:\n    """One tile, every op worth doing there today, and what must be drawn at the depot first."""\n\n    __slots__ = ("tile", "ops", "prize", "service", "needs", "mandatory")\n\n    def __init__(self, tile, ops):\n        self.tile = tile\n        self.ops = [(op, item) for op, item, _p in ops]\n        self.prize = sum(p for _o, _i, p in ops)\n        self.service = len(ops)\n        self.needs = collections.Counter(i for o, i, _p in ops if i and o in DRAWN)\n        self.mandatory = any(p >= MANDATORY for _o, _i, p in ops)\n\n    def __repr__(self):\n        return f"Node{self.tile}{[o for o, _ in self.ops]}@${self.prize:.0f}/{self.service}t"\n\n\ndef build_nodes(tiles, day, shed, carried, unlocked, pinned):\n    """Every tile worth visiting today, as routing nodes.\n\n    `carried` is the union of what the crew already holds, so a task whose input is neither in the\n    shed nor in a hand is never queued at all -- the deadlock that cost $45,623 was a unit holding\n    the board\'s highest-priority job while standing on an empty shed.\n    """\n    have_wheat = shed.get("WHEAT", 0) > 0 or carried.get("WHEAT", 0) > 0\n    have_fert = shed.get("FERTILIZER", 0) > 0 or carried.get("FERTILIZER", 0) > 0\n    nodes = []\n    for y, row in enumerate(tiles):\n        for x, cell in enumerate(row):\n            tile = (x, y)\n            if tile in pinned or not isinstance(cell, dict):\n                continue\n            if R.quadrant_of(x, y) not in unlocked:\n                continue\n            kind = cell.get("kind")\n            if kind == "PLANT":\n                ops = crop_ops(cell, day, have_fert)\n            elif "animal" in cell:\n                ops = animal_ops(cell, day, have_wheat)\n            elif kind in ("PASTURE", "COOP"):\n                ops = []\n                for a in R.ANIMAL_NAMES:\n                    if ANIMALS[a]["structure"] != kind:\n                        continue\n                    if shed.get(a, 0) > 0 or carried.get(a, 0) > 0:\n                        ops = [("PLACE", a, ANIMALS[a]["cost"] + _animal_remaining(\n                            {"animal": a, "placed_day": day}, day))]\n                        break\n            elif kind == "WEED":\n                # Worth exactly the planting it unblocks, so late in the season a weed is furniture.\n                best = max((plant_prize(c, day) for c in R.CROPS), default=0)\n                ops = [("DIG", None, best * 0.5)] if best else []\n            else:\n                ops = []\n            if ops:\n                nodes.append(Node(tile, ops))\n\n    for tile, (op, item, prize) in pinned.items():\n        if R.quadrant_of(tile[0], tile[1]) in unlocked:\n            nodes.append(Node(tile, [(op, item, prize)]))\n    return nodes\n\n\n# ---------------------------------------------------------------------------------------------\n# routing: cluster-first is implicit in cheapest-insertion, then 2-opt each route\n# ---------------------------------------------------------------------------------------------\n\ndef _path_len(start, seq):\n    d, cur = 0, start\n    for t in seq:\n        d += dist(cur, t)\n        cur = t\n    return d\n\n\ndef _two_opt(start, seq, keep_prefix=0):\n    """Standard 2-opt on an OPEN path. `keep_prefix` pins the depot stop at the front."""\n    if len(seq) - keep_prefix < 3:\n        return seq\n    best = list(seq)\n    best_len = _path_len(start, best)\n    improved = True\n    while improved:\n        improved = False\n        for i in range(keep_prefix, len(best) - 1):\n            for j in range(i + 1, len(best)):\n                cand = best[:i] + best[i:j + 1][::-1] + best[j + 1:]\n                cl = _path_len(start, cand)\n                if cl < best_len - 1e-9:\n                    best, best_len, improved = cand, cl, True\n    return best\n\n\ndef plan_routes(units, nodes, budget, depots=SHED, carry=None):\n    """Assign nodes to units and order each unit\'s tour. Returns `{unit: [Node, ...]}`.\n\n    Greedy cheapest-insertion on **prize / marginal cost**, which is the standard Team Orienteering\n    heuristic, then 2-opt per route. Mandatory nodes are placed first and unconditionally, so a\n    hungry animal is never outbid by a melon.\n\n    The marginal cost of inserting node `n` between `prev` and `next` is\n    `d(prev,n) + d(n,next) - d(prev,next) + n.service`, evaluated in O(1), so the whole assignment is\n    a few hundred thousand integer operations -- run once per replan, not per turn.\n    """\n    # **Only shed cells we OWN are depots.** `_spawn_hand` ignores ownership, so hands wake on `(5,4)`,\n    # `(4,5)` and `(5,5)`, which are LOCKED until $1,000, $2,000 and $7,000 of land is bought -- and\n    # `_apply_unit_action` returns on a LOCKED tile *before* it reaches PICKUP. Treating all four as\n    # depots put three of five hands on a locked cell emitting a PICKUP that did nothing, all day.\n    depots = tuple(depots) or SHED\n    routes = {u: [] for u in range(len(units))}\n    used = {u: 0 for u in range(len(units))}\n    depot = {u: collections.Counter() for u in range(len(units))}\n    depot_at = {u: None for u in range(len(units))}\n    # **A vehicle arrives with a load.** Hands are hired through the morning and every hire forces a\n    # replan, so by mid-morning units are already carrying wheat, fertilizer and animals. Costing every\n    # item-bearing stop as a fresh shed trip sent a unit with an empty hand to an empty shed while\n    # another stood holding the feed: eight wheat carried, four hungry animals, FEED 0, herd gone.\n    held = {u: collections.Counter((carry or {}).get(u) or {}) for u in range(len(units))}\n    left = list(nodes)\n\n    def seq(u):\n        out = []\n        if depot_at[u] is not None:\n            out.append(depot_at[u])\n        out.extend(n.tile for n in routes[u])\n        return out\n\n    def delta(u, n, i):\n        """Turn cost of putting `n` at position `i` of unit `u`\'s route, depot stop included."""\n        s = seq(u)\n        off = 1 if depot_at[u] is not None else 0\n        at = i + off\n        prev = s[at - 1] if at > 0 else units[u]\n        nxt = s[at] if at < len(s) else None\n        d = dist(prev, n.tile) + (dist(n.tile, nxt) - dist(prev, nxt) if nxt else 0)\n        extra = n.service\n        short = _uncovered(u, n)\n        if short:\n            if depot_at[u] is None:\n                # One shed trip per unit per day: PICKUP is unbounded in quantity, so the only cost\n                # of another pen on the round is the walk to it.\n                home = min(depots, key=lambda c: dist(c, units[u]))\n                first = s[0] if s else n.tile\n                extra += len(short) + dist(units[u], home) + dist(home, first) - dist(units[u], first)\n            else:\n                extra += sum(1 for it in short if depot[u][it] == 0)\n        return d + extra\n\n    def _uncovered(u, n):\n        """What this node needs that the unit is not already carrying, after everything assigned so far."""\n        return {it: c - held[u][it] for it, c in n.needs.items() if c > held[u][it]}\n\n    def commit(u, n, i, c):\n        """Put `n` at position `i` of unit `u`, paying `c` turns and booking whatever it must draw."""\n        short = _uncovered(u, n)\n        routes[u].insert(i, n)\n        used[u] += c\n        # Consume the load first, and only draw the remainder. `held` going down as stops are added\n        # is what stops three pens on one unit each costing a shed trip.\n        for it, qty in n.needs.items():\n            held[u][it] = max(0, held[u][it] - qty)\n        if short:\n            if depot_at[u] is None:\n                depot_at[u] = min(depots, key=lambda t: dist(t, units[u]))\n            depot[u].update(short)\n\n    order = sorted(left, key=lambda n: -n.prize)\n    # Mandatory nodes are assigned in their own pass, so a hungry animal cannot be outbid on ratio by a\n    # melon that happens to be nearer. Within the pass they still order by cost.\n    for pool in ([n for n in order if n.mandatory], [n for n in order if not n.mandatory]):\n        remaining = list(pool)\n        # **Parallel insertion, least-loaded unit first.** The obvious construction -- scan every\n        # (node, unit, position) and commit the single best `prize / delta` -- minimises total walking,\n        # and total walking is the wrong objective here. Units are hired for the whole day whether they\n        # move or not, so an idle unit\'s turns are free and the scarce resource is per-unit TIME.\n        #\n        # On a serpentine field that distinction is decisive: appending the next tile to the unit\n        # already standing on the previous one costs delta 2, while starting an idle unit from the shed\n        # costs delta 6, so the sequential rule packs one vehicle and starves the rest. Day 0 of seed 11\n        # measured `10, 9, 2, 0, 0` across five units -- two saturated at 21 and 20 turns against a\n        # budget of 21, two given nothing -- and six of the twenty-one pinned jobs were never started.\n        #\n        # But pure round-robin -- every unit claims one node per round -- overcorrects, because it hands\n        # a job to a distant idle unit even when a loaded one is standing beside it. Measured over five\n        # seasons it converted 776 idle turns into 742 extra MOVES for no extra work at all\n        # (`moves per work op` 0.94 -> 1.26) and cost the herd 26 feeds, since a far unit now outbid the\n        # unit already at the pen.\n        #\n        # So: keep the global cheapest-insertion rule, and only force the spread when a unit reaches its\n        # fair share of the day. The cap starts at `budget / n_units` and relaxes in `n_units` steps, so\n        # walking is minimised inside each pass and no unit can eat the whole field before the others\n        # have been offered any of it. The final pass has cap == budget, so nothing is ever left unserved\n        # that the plain rule would have served.\n        n_u = max(1, len(units))\n        for step in range(1, n_u + 1):\n            cap = {u: budget[u] * step / n_u for u in range(len(units))}\n            while remaining:\n                best = None\n                for n in remaining:\n                    for u in range(len(units)):\n                        for i in range(len(routes[u]) + 1):\n                            c = delta(u, n, i)\n                            if used[u] + c > cap[u]:\n                                continue\n                            score = n.prize / max(1, c)\n                            if best is None or score > best[0]:\n                                best = (score, n, u, i, c)\n                if best is None:\n                    break                          # nothing more fits under this cap; relax it\n                _s, n, u, i, c = best\n                commit(u, n, i, c)\n                remaining.remove(n)\n\n    for u in routes:\n        if len(routes[u]) < 3:\n            continue\n        by_tile = {n.tile: n for n in routes[u]}\n        start = depot_at[u] if depot_at[u] is not None else units[u]\n        ordered = _two_opt(start, [n.tile for n in routes[u]])\n        new = [by_tile[t] for t in ordered]\n        cost = _path_len(start, ordered) + sum(n.service for n in new)\n        if depot_at[u] is not None:\n            cost += dist(units[u], depot_at[u]) + len(depot[u])\n        if cost <= budget[u]:\n            routes[u] = new\n            used[u] = cost\n\n    return {u: dict(route=routes[u], depot=depot_at[u], draw=depot[u], cost=used[u])\n            for u in routes}\n'
_SOURCES['kagg.search.schedule_agent'] = '"""A schedule-driven agent that reads the board every turn. No emitter, no dead reckoning, no model.\n\n`dayplan.emit` renders a schedule to a 720-turn tape by **predicting** the state it will act on, and that\nprediction is where the season goes. Measured against the tape\'s own schedule -- ops EMITTED against ops\nthat actually LANDED:\n\n                        ours emit/land    tape emit/land\n    CARE                     312 / 150         308 / 308\n    FEED                     312 / 142         319 / 319\n    WATER                    766 / 455         851 / 846\n    COLLECT_FERTILIZER       297 / 143         318 / 318\n    HARVEST                  286 / 149         338 / 337\n\n48% against ~100%. Eight separate silent bugs were fixed in a single day -- a hand waking on the locked\n`(5,5)` corner, ops written to an unhired slot, a tour truncated past the end of the day, two parcels\nordered against a bank the day\'s own purchases had already spent, animals drawn from a shed before the\npurchase settled -- and every one is the same bug: **emitting an op without checking the state it lands\nin.**\n\nThe environment hands that state over for free, every turn:\n\n    obs["farms"][me]["tiles"]     the board, with `watered_today`, `yield_units`, `fed_today`,\n                                 `cared_today`, `fertilizer_available`, `consecutive_unwatered`\n    obs["farms"][me]["farmer"]    where the farmer stands -- no dead reckoning\n    obs["farms"][me]["hands"]     every hand, so an op cannot go to a unit we do not own\n    obs["farms"][me]["money"]     so a purchase is never ordered against a bank that cannot pay\n    obs["private"]["shed"]        so an animal is never drawn from an empty shed\n    obs["private"]["seeds"]       so PLANT is never blocked by the atomic-seed rule\n\nSo this agent plans no tour. Each turn each unit either performs its op or takes one step towards it, and\nnext turn the board is read again. The whole failure class becomes unrepresentable rather than fixable one\nbug at a time.\n\nThe schedule stays thin -- counts per day, no tile coordinates -- because that is what our own optimiser\ncan produce. `scripts/build_schedule.py` generates it; `scripts/schedule_ladder.py` scores it.\n"""\n\nimport collections\n\nfrom . import router as RT\nfrom . import routines as R\n\nTPD = R.TURNS_PER_DAY\nSHED = set(R.shed_access_tiles())\nSPAWN = tuple(R.SPAWN)\nSTEP = {"NORTH": (0, -1), "SOUTH": (0, 1), "EAST": (1, 0), "WEST": (-1, 0)}\nCROP = R.CROP_TABLE\n\n#: `shedCapacity`, the env default. DROP does not clamp -- it `del`s every item after taking whatever\n#: fits (`kaggriculture.py:333`), so dropping into a full shed destroys the load rather than refusing.\nSHED_CAPACITY = 100\n\n#: Days of feed to hold per animal. 1 is the consumption rate and leaves no slack; the tape carries\n#: over two. Also the multiplier the sell guard protects, so raising it withholds more wheat from sale.\nFEED_DAYS = 2\n\nLAND_PRICES = R.LAND_PRICES\n\n#: Task priority. Pen work first because it is nearly free -- the herd lives on the shed cells, so FEED,\n#: CARE and COLLECT_FERTILIZER cost no walk -- and because two missed feeds and the animal is gone\n#: outright (`kaggriculture.py:786`). A thirsty tile next: two dry days makes it a weed, and weeded ground\n#: refuses PLANT until someone digs it, so the tile is dead for the season.\nRANK = dict(FEED=0, CARE=1, COLLECT_FERTILIZER=2, WATER_THIRSTY=3, HARVEST=4,\n            PLACE=5, BUILD=6, WATER=7, FERTILIZE=8, PLANT=9, DIG=10)\n\n\ndef _owned(tile, unlocked):\n    return R.quadrant_of(tile[0], tile[1]) in unlocked\n\n\ndef _mobile(pos, unlocked):\n    """Can this unit do anything at all today?\n\n    A LOCKED tile no-ops every op except MOVE (`kaggriculture.py:322`), and MOVE onto a LOCKED tile is\n    refused as well (:313). Hands wake on `(5,4)`, `(4,5)` and `(5,5)` in rotation, so while only NW is\n    owned the third hand of every four wakes on `(5,5)` -- whose four orthogonal neighbours are all in\n    locked quadrants -- and is boxed in for the whole day. It cannot even be walked home.\n\n    That is the game\'s rule, not ours, and the tape pays it too. What is ours is what the planner did\n    about it: it assigned that unit four jobs, the executor dropped them as unreachable, the unit read\n    as idle, and the top-up handed it the SAME four jobs back on every turn to dusk. Work parked on a\n    boxed-in hand was never offered to a hand that could reach it, so day 0 finished a pen short.\n    """\n    if _owned(pos, unlocked):\n        return True\n    x, y = pos\n    return any(_owned((x + dx, y + dy), unlocked)\n               for dx, dy in ((0, -1), (0, 1), (1, 0), (-1, 0))\n               if 0 <= x + dx < R.BOARD_SIZE and 0 <= y + dy < R.BOARD_SIZE)\n\n\ndef _step_towards(src, dst, unlocked):\n    """One legal step from `src` towards `dst`, or None.\n\n    A move onto LOCKED is ignored by the environment without spending the turn, so the destination has to\n    be CHECKED rather than assumed -- that check is the whole of what dead reckoning could not do.\n    """\n    src, dst = tuple(src), tuple(dst)\n    if src == dst:\n        return None\n    here = abs(src[0] - dst[0]) + abs(src[1] - dst[1])\n    order = []\n    if dst[1] != src[1]:\n        order.append("SOUTH" if dst[1] > src[1] else "NORTH")\n    if dst[0] != src[0]:\n        order.append("EAST" if dst[0] > src[0] else "WEST")\n    order += [m for m in ("NORTH", "SOUTH", "EAST", "WEST") if m not in order]\n    for m in order:\n        dx, dy = STEP[m]\n        nxt = (src[0] + dx, src[1] + dy)\n        if not (0 <= nxt[0] < R.BOARD_SIZE and 0 <= nxt[1] < R.BOARD_SIZE):\n            continue\n        if not _owned(nxt, unlocked):\n            continue\n        if abs(nxt[0] - dst[0]) + abs(nxt[1] - dst[1]) < here:\n            return m\n    return None\n\n\ndef _nearest_empty(tiles, unlocked, origin, skip=frozenset()):\n    """Nearest empty owned tile, preferring ground that touches what we already work.\n\n    Adjacency beats raw distance because every tile is revisited ~20 times a season: five adjacent tiles\n    is a four-step tour, five spread round a ring is twelve.\n    """\n    worked = {(x, y) for y, r in enumerate(tiles) for x, c in enumerate(r) if isinstance(c, dict)}\n    best = None\n    for y, r in enumerate(tiles):\n        for x, c in enumerate(r):\n            t = (x, y)\n            if c is not None or t in skip or t in SHED or not _owned(t, unlocked):\n                continue\n            touch = sum(1 for w in worked if abs(w[0] - x) + abs(w[1] - y) == 1)\n            key = (-touch, abs(x - origin[0]) + abs(y - origin[1]), t)\n            if best is None or key < best[0]:\n                best = (key, t)\n    return best[1] if best else None\n\n\ndef _next_ground(order, tiles, taken):\n    """The next tile in the placement sweep that the board says is free.\n\n    Replaces `_nearest_empty`\'s per-tile `(adjacency, distance)` score, which grew a snake out from\n    whichever tile was planted first. Measured on tour length -- the thing paid ~20 times a season --\n    the two are level inside one quadrant, and the sweep wins by 23-35% once land is bought:\n\n        quadrants        tiles     sweep    adjacency-greedy\n        NW               8-24      8-24     9-24\n        NW NE SW         20        20       31\n        NW NE SW         30        37       48\n\n    That is the case the farm actually plays, because the parcels arrive around days 7-10 and the crew\n    works twenty to thirty tiles from then on.\n    """\n    for t in order:\n        if t not in taken and tiles[t[1]][t[0]] is None:\n            return t\n    return None\n\n\ndef _emit(op, item):\n    if op == "BUILD":\n        return ["BUILD_COOP" if R.ANIMALS[item]["structure"] == "COOP" else "BUILD_PASTURE"]\n    if op == "PLANT":\n        return ["PLANT", item]\n    if op == "PLACE":\n        return ["PLACE", item, 1]\n    return [op]\n\n\ndef _live_ops(tile, cell, day, inv, pins, seeds):\n    """The ops still worth doing at `tile`, **re-derived from the live board every turn**.\n\n    This is the whole trick to committing to a tour without going back to predicting state. The route\n    fixes *which tiles* a unit visits and in what order -- stable, because a tile is a tile. What it\n    does when it gets there is read off the cell, so a stop whose work another unit already did, or\n    whose crop weeded overnight, simply returns nothing and the stop is dropped.\n\n    Item-bearing ops are gated on **this unit\'s** inventory rather than the shed. Gating on the shed is\n    what let a unit stand on a pen emitting FEED with no wheat in hand, silently no-oping and re-picking\n    the same op forever.\n    """\n    if tile in pins:\n        op, item, _prize = pins[tile]\n        if cell is not None:\n            return []\n        if op == "PLANT":\n            return [("PLANT", item)] if seeds.get(item, 0) > 0 else []\n        return [("BUILD", item)]\n    if not isinstance(cell, dict):\n        return []\n    kind = cell.get("kind")\n    if kind == "PLANT":\n        ops = RT.crop_ops(cell, day, inv.get("FERTILIZER", 0) > 0)\n    elif "animal" in cell:\n        ops = RT.animal_ops(cell, day, inv.get("WHEAT", 0) > 0)\n    elif kind in ("PASTURE", "COOP"):\n        ops = next(([("PLACE", a, 0)] for a in R.ANIMAL_NAMES\n                    if R.ANIMALS[a]["structure"] == kind and inv.get(a, 0) > 0), [])\n    elif kind == "WEED":\n        ops = [("DIG", None, 0)]\n    else:\n        ops = []\n    return [(o, i) for o, i, _p in ops]\n\n\ndef _refresh_pins(state, sched, day, tiles, unlocked):\n    """Keep the schedule-derived tiles PINNED until the board resolves them.\n\n    A board task carries its own identity -- the tile *is* the task -- but `PLANT a strawberry` and\n    `BUILD a pasture` have none until something assigns them ground. `_nearest_empty` re-derived that\n    ground every turn, so a planned `PLANT at (2,3)` became `(2,4)` the next turn and the plan was\n    dropped as stale: the committed-tour port banked **$0** with 211 work ops a season for exactly this\n    reason. Pinning once, and only re-pinning when the board invalidates the choice, is the fix.\n\n    Both targets are **cumulative**, because a per-day row that failed on a thin bank was never retried:\n    5 pens all season against a schedule\'s 14, and therefore every animal figure at ~21% of the tape\'s.\n    Plantings additionally expire -- `plant_prize` is 0 once the season cannot finish the crop -- so late\n    ground is left empty rather than seeded with something that will never mature.\n    """\n    pins = state["pins"]\n    order = RT.field_order(unlocked)\n    for t in list(pins):\n        x, y = t\n        if tiles[y][x] is not None:                       # planted, built, or a weed took the ground\n            pins.pop(t)\n        elif pins[t][0] == "PLANT" and RT.plant_prize(pins[t][1], day) <= 0:\n            pins.pop(t)\n        elif not _owned(t, unlocked):\n            pins.pop(t)\n    taken = set(pins)\n\n    structures = sum(1 for r in tiles for c in r\n                     if isinstance(c, dict) and (c.get("kind") in ("PASTURE", "COOP")\n                                                 or "animal" in c))\n    want_pens = sum(int(sched.get(d, {}).get("builds", 0) or 0) for d in range(day + 1))\n    wanted = [a for d in sorted(sched) if d <= day for a in (sched[d].get("places") or [])]\n    have = structures + sum(1 for v in pins.values() if v[0] == "BUILD")\n    while have < want_pens:\n        a = wanted[have] if have < len(wanted) else "COW"\n        # A pen ON a shed-access cell runs its whole daily loop -- draw feed, feed, care, collect,\n        # harvest -- without a single move, so those four cells are worth more than any field tile.\n        spot = next((c for c in R.shed_access_tiles()\n                     if _owned(c, unlocked) and tiles[c[1]][c[0]] is None and c not in taken), None)\n        spot = spot or _next_ground(order, tiles, taken)\n        if spot is None:\n            break\n        pins[spot] = ("BUILD", a, R.ANIMALS[a]["cost"])\n        taken.add(spot)\n        have += 1\n\n    want = collections.Counter()\n    for d in sorted(sched):\n        if d <= day:\n            want.update(sched[d].get("plants") or [])\n    live = collections.Counter(v[1] for v in pins.values() if v[0] == "PLANT")\n    for crop, qty in want.items():\n        if crop not in CROP or RT.plant_prize(crop, day) <= 0:\n            continue\n        for _ in range(qty - state["planted"][crop] - live[crop]):\n            spot = _next_ground(order, tiles, taken)\n            if spot is None:\n                break\n            pins[spot] = ("PLANT", crop, RT.plant_prize(crop, day))\n            taken.add(spot)\n    return pins\n\n\ndef _router_acts(state, sched, day, hour, tiles, units, invs, shed, seeds, unlocked):\n    """One turn of the routed plan: replan if the crew or the work changed, then walk the tours."""\n    pins = _refresh_pins(state, sched, day, tiles, unlocked)\n    carried = collections.Counter()\n    for iv in invs:\n        carried.update(iv)\n    budget = [max(0, TPD - hour - 1)] * len(units)\n    routes = state["routes"]\n    # Only shed cells inside a quadrant we own. A hand wakes on a LOCKED one and a LOCKED tile no-ops\n    # before PICKUP is ever reached, so treating all four as depots strands the hand for the whole day.\n    depots = tuple(c for c in R.shed_access_tiles() if _owned(c, unlocked)) or (SPAWN,)\n    load = {u: collections.Counter(invs[u] if u < len(invs) else {}) for u in range(len(units))}\n\n    def nodes_for(skip):\n        return [n for n in RT.build_nodes(tiles, day, shed, carried, unlocked, pins)\n                if n.tile not in skip]\n\n    # Only units that can legally act are vehicles. A boxed-in hand is not a slow vehicle, it is no\n    # vehicle at all, and planning work onto it silently deletes that work for the day.\n    live = [u for u in range(len(units)) if _mobile(units[u], unlocked)]\n\n    if state["crew"] != len(live) or not routes:\n        # A full replan only when the crew changes -- hands are hired through the morning, so the dawn\n        # plan genuinely cannot know how many vehicles it has.\n        sub = RT.plan_routes([units[u] for u in live], nodes_for(set()),\n                             [budget[u] for u in live], depots,\n                             {k: load[u] for k, u in enumerate(live)})\n        state["routes"] = routes = {u: sub[k] for k, u in enumerate(live)}\n        state["crew"] = len(live)\n    else:\n        idle = [u for u in live if not routes.get(u, {}).get("route")]\n        if idle:\n            # **Top up the idle units only.** Replanning everybody would break the commitment of a unit\n            # already three steps into a tour, which is the thrash the per-turn greedy had.\n            busy = {n.tile for u, st in routes.items() if u not in idle for n in st["route"]}\n            sub = RT.plan_routes([units[u] for u in idle], nodes_for(busy),\n                                 [budget[u] for u in idle], depots,\n                                 {k: load[u] for k, u in enumerate(idle)})\n            for k, u in enumerate(idle):\n                routes[u] = sub[k]\n\n    acts = []\n    for u, pos in enumerate(units):\n        inv = collections.Counter(invs[u] if u < len(invs) else {})\n        st = routes.get(u)\n        if st is None:\n            acts.append(["PASS"])\n            continue\n\n        # ------------------------------------------------------------------ one shed trip, in bulk\n        # `PICKUP` is unbounded -- `n = min(n, available)` then `_inv_add(inv, item, n)` -- so a unit\n        # servicing six pens draws six wheat in ONE turn. Drawing one at a time, as the greedy did, made\n        # every pen a shed round trip and is most of why FEED landed on 81% of animal-days.\n        draw = None\n        for item, qty in st["draw"].items():\n            short = qty - inv.get(item, 0)\n            if short > 0 and shed.get(item, 0) > 0:\n                draw = (item, min(short, shed[item]))\n                break\n        if draw is None:\n            st["draw"].clear()\n        elif pos in depots:\n            shed[draw[0]] -= draw[1]\n            acts.append(["PICKUP", draw[0], draw[1]])\n            continue\n        else:\n            home = min(depots, key=lambda c: abs(c[0] - pos[0]) + abs(c[1] - pos[1]))\n            m = _step_towards(pos, home, unlocked)\n            if m:\n                acts.append([m])\n                continue\n            st["draw"].clear()\n\n        # ------------------------------------------------------------------ walk the committed tour\n        act = ["PASS"]\n        while st["route"]:\n            node = st["route"][0]\n            if pos != node.tile:\n                m = _step_towards(pos, node.tile, unlocked)\n                if m is None:                       # unreachable: drop the stop rather than idle on it\n                    st["route"].pop(0)\n                    continue\n                act = [m]\n                break\n            ops = _live_ops(node.tile, tiles[node.tile[1]][node.tile[0]], day, inv, pins, seeds)\n            if not ops:\n                st["route"].pop(0)\n                continue\n            op, item = ops[0]\n            act = _emit(op, item)\n            if op == "PLANT":\n                state["planted"][item] += 1\n                seeds[item] -= 1\n                pins.pop(node.tile, None)\n            elif op == "BUILD":\n                # Keep the stop: next turn the cell reads PASTURE and `_live_ops` returns the PLACE,\n                # so the animal goes in without a second trip.\n                pins.pop(node.tile, None)\n            break\n\n        # ------------------------------------------------------------------ the return leg\n        # A one-way sweep cannot sell what it picks up. Measured against the tape on days 1-3 of seed\n        # 11: `EAST 0/10, 0/17, 0/15` and `SOUTH 0/13, 0/14, 0/14` -- our crew never turned back towards\n        # the shed on three consecutive days while the tape emitted DROP one to two times daily, so our\n        # harvest could not reach the market until `_drop_inventories_to_shed` ran overnight.\n        #\n        # The turns cost nothing: this only fires once the tour is done and the unit would PASS. DROP\n        # moves the WHOLE inventory and DELETES anything the shed has no room for\n        # (`kaggriculture.py:333`), so it is refused when the shed is near full.\n        if act == ["PASS"] and not st["route"] and any(v > 0 for v in inv.values()):\n            if sum(shed.values()) + sum(inv.values()) <= SHED_CAPACITY:\n                if pos in depots:\n                    for item, qty in inv.items():\n                        if qty > 0:\n                            shed[item] = shed.get(item, 0) + qty\n                    act = ["DROP"]\n                else:\n                    m = _step_towards(pos, min(depots, key=lambda c: abs(c[0] - pos[0])\n                                               + abs(c[1] - pos[1])), unlocked)\n                    act = [m] if m else act\n        acts.append(act)\n    return acts\n\n\ndef make_agent(schedule, me=0, router=True):\n    """`agent(obs, config) -> action`.\n\n    `router=True` solves the day as a Team Orienteering Problem (`kagg/search/router.py`): tiles are\n    pinned, tours are committed, and each stop\'s ops are re-derived from the live board. `router=False`\n    is the earlier per-turn greedy, kept only so the two can be measured on one seed list.\n    """\n    sched = {int(k): v for k, v in schedule.items()}\n    state = dict(assigned={}, hired=0, day=-1, tour={}, bought=collections.Counter(),\n                 pins={}, routes={}, crew=-1, planted=collections.Counter(),\n                 ordered=collections.Counter())\n\n    def agent(obs, config=None):\n        day = int(obs.get("day", 0) or 0)\n        hour = int(obs.get("hour", 0) or 0)\n        farms = obs.get("farms") or []\n        if len(farms) <= me:\n            return {"farmer": ["PASS"], "hands": [], "market": []}\n        farm = farms[me]\n        priv = obs.get("private") or {}\n        shed = collections.Counter(priv.get("shed") or {})\n        seeds = collections.Counter(priv.get("seeds") or {})\n        invs = priv.get("inventories") or [{}]\n        tiles = farm["tiles"]\n        money = float(farm["money"])\n        unlocked = set(farm.get("unlocked_quadrants") or ["NW"])\n        row = sched.get(day, {})\n\n        if day != state["day"]:              # hands are dismissed nightly, so every claim is stale\n            # `ordered` is per-day book-keeping for market orders that must happen ONCE, not once per\n            # turn. Without it the agent re-issued the day\'s animals and seed on all 24 turns -- day 0\n            # bought four animals at turn 0 and four more at turn 1 until the bank was empty, which is why\n            # it reached day 1 on $61 and could then never afford a hand again.\n            state.update(day=day, assigned={}, hired=0, ordered=collections.Counter(), tour={},\n                         routes={}, crew=-1)          # `pins` and `planted` survive the night by design\n\n        units = [tuple(farm["farmer"])] + [tuple(h) for h in (farm.get("hands") or [])]\n\n        if router:\n            acts = _router_acts(state, sched, day, hour, tiles, units, invs, shed,\n                                seeds, unlocked)\n        else:\n            # ------------------------------------------------------------------ what the BOARD needs now\n            # Carried stock, computed once: a task whose input is neither in the shed nor in a hand must not be\n            # queued at all, or the unit that takes it deadlocks holding a job it can never start.\n            wheat_carried = any(collections.Counter(iv).get("WHEAT", 0) > 0 for iv in invs)\n            tasks = []\n            for y, r in enumerate(tiles):\n                for x, cell in enumerate(r):\n                    t = (x, y)\n                    if not isinstance(cell, dict):\n                        continue\n                    kind = cell.get("kind")\n                    if kind == "PLANT":\n                        info = CROP[cell["crop"]]\n                        age = day - cell["planted_day"]\n                        if not cell["watered_today"]:\n                            thirsty = cell["consecutive_unwatered"] >= 1\n                            in_window = (not info["ongoing"]\n                                         and (info["max_day"] + 1) // 2 <= age <= info["max_day"])\n                            if thirsty or in_window or info["ongoing"]:\n                                tasks.append((RANK["WATER_THIRSTY"] if thirsty else RANK["WATER"],\n                                              t, "WATER", None))\n                        if cell["yield_units"] > 0 and age >= info["first"]:\n                            tasks.append((RANK["HARVEST"], t, "HARVEST", None))\n                        # **FERTILIZE, which the agent never did at all.** It doubles a tile\'s yield, but only\n                        # on a day the tile is ALSO watered: `_daily_refresh_plants` computes\n                        # `fertilized = was_watered and fertilized_until_day >= current_day`, and the one-shot\n                        # WATER bonus is `2 if fertilized else 1`. It lasts three days (day..day+2), so it is\n                        # worth applying just before a producing stretch and worthless outside one. The tape\n                        # applies 107; we applied 0 and sold the fertilizer instead.\n                        # Fertilizer in the shed OR already in a hand. A unit that has just run\n                        # COLLECT_FERTILIZER is carrying one, and testing the shed alone found none -- because\n                        # the sell list dumps every unit of FERTILIZER from the shed each turn, so it is gone\n                        # before any tile can be fertilized. FERTILIZE fired 0 times against the tape\'s 107.\n                        carried = any(collections.Counter(iv).get("FERTILIZER", 0) > 0 for iv in invs)\n                        if (cell["fertilized_until_day"] < day\n                                and age >= info["first"] - 2\n                                and (shed.get("FERTILIZER", 0) > 0 or carried)):\n                            tasks.append((RANK["FERTILIZE"], t, "FERTILIZE", "FERTILIZER"))\n                    elif "animal" in cell:\n                        # **Only queue a FEED if the wheat exists somewhere.** Without this a unit took the\n                        # job, walked to the shed, found it empty, PASSed -- and because it still HELD the job\n                        # it re-picked the same FEED next turn and froze there. Measured on the winner\'s\n                        # schedule: FEED 0 with 83 idle unit-turns and live animals in the pens, day after day,\n                        # because rank 0 kept every hand queued behind wheat that never arrived. Same silent\n                        # shape as the rest: a failed precondition that does nothing instead of reporting.\n                        if not cell["fed_today"] and (shed.get("WHEAT", 0) > 0 or wheat_carried):\n                            tasks.append((RANK["FEED"], t, "FEED", "WHEAT"))\n                        if not cell["cared_today"]:\n                            tasks.append((RANK["CARE"], t, "CARE", None))\n                        if cell["fertilizer_available"]:\n                            tasks.append((RANK["COLLECT_FERTILIZER"], t, "COLLECT_FERTILIZER", None))\n                        if cell["yield_units"] > 0:\n                            tasks.append((RANK["HARVEST"], t, "HARVEST", None))\n                    elif kind == "WEED":\n                        tasks.append((RANK["DIG"], t, "DIG", None))\n                    elif kind in ("PASTURE", "COOP"):\n                        # An empty structure -- restock it if a matching animal is in the shed **or already in\n                        # a hand**. Testing the shed alone dropped the task the instant the animal was picked\n                        # up, so a unit that had just built a pen and was holding a cow forgot to place it:\n                        # day 0 raised 4 pens and stocked 1.\n                        for a in R.ANIMAL_NAMES:\n                            if R.ANIMALS[a]["structure"] != kind:\n                                continue\n                            if shed.get(a, 0) > 0 or any(collections.Counter(iv).get(a, 0) > 0\n                                                         for iv in invs):\n                                tasks.append((RANK["PLACE"], t, "PLACE", a))\n                                break\n\n            # pens the schedule still wants, on shed cells first: a pen on `(4,4)` runs its whole daily loop\n            # -- draw feed, feed, care, collect, harvest, deposit -- without a single move.\n            standing = sum(1 for r in tiles for c in r\n                           if isinstance(c, dict) and c.get("kind") in ("PASTURE", "COOP"))\n            want_by_now = sum(int(sched.get(d, {}).get("builds", 0) or 0) for d in range(day + 1))\n            claimed_spots = {t for _r, t, _o, _i in tasks}\n            # **The schedule is a running TARGET, not a one-shot instruction.** Iterating only today\'s `places`\n            # meant a pen we could not afford on its named day was never built again: 5 pens all season against\n            # the schedule\'s 14, so 72 animal-days against the tape\'s 343 -- and every animal figure was ~21% of\n            # the tape\'s purely because the herd was 21% the size. Servicing was already perfect at that size:\n            # CARE 100% of animal-days, fertilizer collected 100%. Catch up whenever a beast is in the shed.\n            want_animals = [a for d in sorted(sched) if d <= day\n                            for a in (sched[d].get("places") or [])]\n            for a in want_animals:\n                if standing >= want_by_now or shed.get(a, 0) <= 0:\n                    break\n                spot = next((c for c in R.shed_access_tiles()\n                             if _owned(c, unlocked) and tiles[c[1]][c[0]] is None\n                             and c not in claimed_spots), None)\n                spot = spot or _nearest_empty(tiles, unlocked, SPAWN, skip=claimed_spots)\n                if spot is None:\n                    break\n                tasks.append((RANK["BUILD"], spot, "BUILD", a))\n                claimed_spots.add(spot)\n                standing += 1\n\n            # plantings the schedule wants today, on ground the BOARD says is empty\n            held = collections.Counter()\n            for crop in (row.get("plants") or []):\n                if seeds.get(crop, 0) - held[crop] <= 0:\n                    continue\n                spot = _nearest_empty(tiles, unlocked, SPAWN, skip=claimed_spots)\n                if spot is None:\n                    break\n                held[crop] += 1\n                claimed_spots.add(spot)\n                tasks.append((RANK["PLANT"], spot, "PLANT", crop))\n\n            tasks.sort(key=lambda z: z[0])\n\n            # ------------------------------------------------------------------ one op per unit\n            claimed, acts = set(), []\n            for u, pos in enumerate(units):\n                inv = collections.Counter(invs[u] if u < len(invs) else {})\n                job = state["assigned"].get(u)\n                if job and not any((t, o, i) == job for _r, t, o, i in tasks):\n                    job = None                    # the board says it is done or gone\n                if job is None:\n                    # **Distance first, rank only to break ties among tasks that are equally close.** Keying\n                    # `(rank, distance)` made rank dominate, so every unit sprinted across the board for the\n                    # highest-priority task anywhere -- twelve hands heading for the same three pens -- and the\n                    # crew spent 78% of its turns walking, ~7 move turns per work turn against the tape\'s 1.44.\n                    # `dayplan._assign` already carried this lesson in a comment and it was not brought over:\n                    # "Rank picks the hand\'s FIRST stop; distance picks every stop after it."\n                    # **Rank picks the hand\'s FIRST stop; distance picks every stop after it.**\n                    # `(rank, distance)` throughout made rank dominate, so every unit sprinted across the board\n                    # for the highest-priority task anywhere -- twelve hands converging on three pens -- at ~7\n                    # move turns per work turn against the tape\'s 1.44. `(distance, rank)` throughout fixed the\n                    # walking to 1.04 and banked $809, because the nearest task is never the important one and\n                    # the herd starved. So: a unit with no tour under way chooses by rank, and a unit that has\n                    # just finished an op continues to whatever is nearest. `dayplan._assign` carried this\n                    # lesson in a comment and it was not brought across.\n                    touring = state["tour"].get(u, False)\n                    best = None\n                    for rank, t, op, item in tasks:\n                        if t in claimed:\n                            continue\n                        d = abs(t[0] - pos[0]) + abs(t[1] - pos[1])\n                        key = (d, rank) if touring else (rank, d)\n                        if best is None or key < best[0]:\n                            best = (key, (t, op, item))\n                    if best is None:\n                        acts.append(["PASS"])\n                        continue\n                    job = best[1]\n                state["assigned"][u] = job\n                tile, op, item = job\n                claimed.add(tile)\n\n                # Anything carried is drawn at a shed cell, and only when it is actually in store.\n                if item and op in ("FEED", "PLACE", "FERTILIZE") and inv.get(item, 0) <= 0:\n                    if pos in SHED and shed.get(item, 0) > 0:\n                        shed[item] -= 1\n                        acts.append(["PICKUP", item, 1])\n                        continue\n                    if shed.get(item, 0) <= 0:\n                        # Nothing to fetch. RELEASE the job so this hand does something useful, instead of\n                        # standing on a shed cell passing while it holds the highest-priority task on the board.\n                        state["assigned"].pop(u, None)\n                        claimed.discard(tile)\n                        acts.append(["PASS"])\n                        continue\n                    home = min(SHED, key=lambda c: abs(c[0] - pos[0]) + abs(c[1] - pos[1]))\n                    m = _step_towards(pos, home, unlocked)\n                    acts.append([m] if m else ["PASS"])\n                    continue\n\n                if pos != tuple(tile):\n                    m = _step_towards(pos, tile, unlocked)\n                    if m is None:\n                        state["assigned"].pop(u, None)\n                        acts.append(["PASS"])\n                    else:\n                        acts.append([m])\n                    continue\n\n                if op == "BUILD":\n                    acts.append(["BUILD_COOP" if R.ANIMALS[item]["structure"] == "COOP"\n                                 else "BUILD_PASTURE"])\n                    state["assigned"][u] = (tile, "PLACE", item)      # place it next turn, same tile\n                elif op == "PLANT":\n                    acts.append(["PLANT", item])\n                    state["assigned"].pop(u, None)\n                    state["tour"][u] = True\n                elif op == "PLACE":\n                    acts.append(["PLACE", item, 1])\n                    state["assigned"].pop(u, None)\n                    state["tour"][u] = True\n                else:\n                    acts.append([op])\n                    state["assigned"].pop(u, None)\n                    state["tour"][u] = True\n\n        # ------------------------------------------------------------------ the market, bank-aware\n        orders = []\n        # How many mouths there are, needed BEFORE the sell loop so the herd\'s feed is not sold.\n        alive = sum(1 for r in tiles for c in r if isinstance(c, dict) and "animal" in c)\n        # SELL first: the proceeds have to be in the bank before anything below spends them, and that\n        # ordering is exactly what decided whether BUY_LAND cleared at all.\n        for prod in ("MELON", "WOOL", "MILK", "STRAWBERRY", "FERTILIZER", "WHEAT"):\n            have = int(shed.get(prod, 0))\n            # **Hold back a few fertilizer.** Applied to a watered, producing tile it doubles the yield --\n            # a strawberry tile is 4 units at $120, so doubling beats the $100 the unit sells for. Dumping\n            # the whole shed every turn is why FERTILIZE never fired at all.\n            if prod == "FERTILIZER":\n                have = max(0, have - 4)\n            # **Never sell the herd\'s feed.** WHEAT is both a crop we grow and the feed we buy, and the\n            # sell list dumps whatever the shed holds. Measured per turn on day 13 with eleven animals:\n            #     h0  BUY_PRODUCT WHEAT 11   shed 0 -> 11\n            #     h1  SELL        WHEAT  6   shed 11 -> 0\n            # every day, all season, which is why `shed WHEAT` read 0 at midday on all thirty days while\n            # the bank climbed to $85,000 and the herd decayed from eleven animals to four. Only the\n            # surplus above one wheat per animal may go.\n            if prod == "WHEAT":\n                have = max(0, have - FEED_DAYS * alive)\n            n = min(have, int((row.get("sells") or {}).get(prod, 0)))\n            # **Do not sell into a collapsed book.** `market_price` falls monotonically in inventory\n            # (`kaggriculture.py:177`) and a SELL walks n units down that curve one at a time, so the\n            # whole stack clears near what the LAST unit fetches. Measured over one season as the herd\n            # came right: wool 123 units -> 138, and wool REVENUE $29,041 -> $21,811. Fifteen extra\n            # units cost $7,230 because the mean price went $234 -> $158.\n            #\n            # Holding is not a loss. Shops drain inventory every 4 steps and the town centre every 12,\n            # at 4x from day 20 (`kaggriculture.py:706-716`), so a collapsed price recovers on its own.\n            #\n            # **Re-offering the day\'s quota on every turn is correct, and two attempts to "fix" it both\n            # lost money.** The quota looks like a dump -- one season\'s wool went 123 units to 138 while\n            # wool REVENUE fell $29,041 to $21,811 -- but neither remedy survived twelve seeds:\n            #\n            #     refuse to sell below 0.5 x base price      -$16,025   goods never clear at all\n            #     cap the quota to a day total, not a turn    -$ 2,653   misses the book\'s recovery\n            #\n            # `market_price` does fall in inventory, but shops drain it every 4 steps and the town\n            # centre every 12, at 4x from day 20 (`kaggriculture.py:706-716`), so the book refills\n            # continuously and a standing offer collects each recovery. An order is only a request:\n            # it fills one unit at a time and stops when the shed empties, so re-offering is free.\n            if n > 0 and len(orders) < 5:\n                orders.append(["SELL", prod, n])\n\n        # **Land: the schedule\'s day is a FLOOR, and the agent buys the first turn it can pay.** The tape\n        # takes the $2,000 parcel at day 10 hour 20, after selling all day. Ordering on a fixed hour lost\n        # it silently and cost 25 tiles for the rest of the season.\n        owned = len(unlocked) - 1\n        if owned < len(LAND_PRICES):\n            need_by = None\n            run = 0\n            for d in sorted(sched):\n                run += int(sched[d].get("land", 0) or 0)\n                if run > owned:\n                    need_by = d\n                    break\n            if need_by is not None and day >= need_by and money >= LAND_PRICES[owned]:\n                orders.append(["BUY_LAND"])\n                money -= LAND_PRICES[owned]\n\n        # Animals: only when the bank covers the cost, so the purchase can never silently no-op.\n        # **Buy against the CUMULATIVE target, not today\'s row.** `animals_bought` is a per-day figure and\n        # `ordered` resets every dawn, so a purchase that failed on a thin bank was never retried. Measured\n        # per turn on the winner\'s schedule: days 8-10 failed on $2-$38, and from day 11 the schedule\'s rows\n        # are empty -- so the agent sat on $8,259 from day 12 to the end of the season and never bought\n        # another animal. 5 pens and 2 animals against a target of 14, which is why every animal figure was\n        # ~21% of the tape\'s while CARE and fertilizer collection were already at 100% of animal-days.\n        want_total = collections.Counter()\n        for dd in sorted(sched):\n            if dd <= day:\n                for a, qty in (sched[dd].get("animals_bought") or {}).items():\n                    want_total[a] += int(qty)\n        for a, qty in want_total.items():\n            if a not in R.ANIMALS:\n                continue\n            # **Compare a PURCHASE target against PURCHASES MADE.** `want_total` is what the schedule\n            # says to buy, so the only correct counter is how many we have bought. It used to compare\n            # against livestock HELD -- alive plus shed plus carried plus bought -- which counted every\n            # living animal twice and bought roughly half the herd the schedule asked for.\n            #\n            # Counting holdings has a second, worse reading: it turns the line into "replace anything\n            # that escapes". Measured, that is a $47,933 mistake. Both arms collapsed -- the greedy from\n            # 45% of the tape to 8% -- because replacing an animal you cannot feed is a deterministic\n            # $400-$500 loss (`kaggriculture.py:786`), and it repeats every two days until the bank is\n            # empty. PLACE went 12 -> 61 a season and the money went with it.\n            #\n            # `bought` never being decremented is therefore the correct behaviour, not a leak: a failed\n            # order does not increment it (the `money >=` test guards that), so a purchase blocked by a\n            # thin bank is still retried, while one that succeeded and then starved is not repeated.\n            for _ in range(max(0, qty - state["bought"][a])):\n                if money >= R.ANIMALS[a]["cost"] and len(orders) < 8:\n                    orders.append(["BUY_ANIMAL", a, 1])\n                    state["bought"][a] += 1\n                    money -= R.ANIMALS[a]["cost"]\n\n        # **Seed against the PINS, not today\'s row.** A planting deferred because the ground or the bank\n        # was not ready still needs its seed on the day it finally happens, and the pins are the only\n        # record of what is still outstanding. Falls back to the row when the pins are not in play.\n        want_seed = collections.Counter()\n        if router:\n            want_seed.update(v[1] for v in state["pins"].values() if v[0] == "PLANT")\n        else:\n            want_seed.update({c: int(q) for c, q in (row.get("seeds") or {}).items()})\n        for crop, qty in want_seed.items():\n            short = int(qty) - int(seeds.get(crop, 0)) - state["ordered"][("seed", crop)]\n            if short > 0 and len(orders) < 9:\n                orders.append(["BUY_SEED", crop, short])\n                state["ordered"][("seed", crop)] += short\n\n        # Feed: one wheat per animal per day, BOUGHT. A wheat tile yields six units and sits on ground\n        # worth far more as melon, so growing feed is a bad trade.\n        # Count wheat a unit is CARRYING as stock. The router draws a whole day\'s feed in one PICKUP, so\n        # the shed reads empty while the crew holds plenty, and buying against the shed alone re-bought\n        # the same feed every day.\n        on_hand = int(shed.get("WHEAT", 0)) + sum(collections.Counter(iv).get("WHEAT", 0)\n                                                 for iv in invs)\n        # **Buy two days, not one.** `alive` is the day\'s CONSUMPTION, and ordering exactly the\n        # consumption leaves no slack anywhere in shed -> PICKUP -> walk -> FEED. Measured over thirty\n        # days: `FED 291 against the tape\'s 319`, `CARE 290 against 308`, 315 animal-days against 325,\n        # and 227 wheat-unit-days in the shed against the tape\'s 990 -- it runs a buffer of more than\n        # two days per animal. Wool realises an identical price in both runs ($236 against $234) and we\n        # still bank $10,575 less of it, so the shortfall is animal-days not worked, not price.\n        short = FEED_DAYS * alive - on_hand - state["ordered"][("feed", "WHEAT")]\n        if alive and short > 0 and len(orders) < 9 and money >= 60 * short:\n            orders.append(["BUY_PRODUCT", "WHEAT", short])\n            state["ordered"][("feed", "WHEAT")] += short\n\n        # Hire TWO a turn. `_spawn_hand` picks by occupancy when the HIRE settles, so a third order in one\n        # turn puts a hand on `(5,5)` in SE with both neighbours locked, unable to move for the whole day.\n        # **Count ORDERS issued today, not orders plus hands.** `have = len(units) - 1 + hired` counted\n        # every landed hire twice -- once in `hands` and once in `hired` -- so a target of 4 was reported\n        # met at 2 and the crew never grew. Hands are dismissed nightly and `hires_today` resets with them,\n        # so the orders issued today are exactly the crew we should end up with.\n        target = int(row.get("hands", 0) or 0)\n        if state["hired"] < target and hour < 8:\n            for _ in range(min(2, target - state["hired"])):\n                orders.append(["HIRE"])\n                state["hired"] += 1\n\n        return {"farmer": acts[0] if acts else ["PASS"], "hands": acts[1:], "market": orders[:10]}\n\n    return agent\n'
